BEGIN
    SET NOCOUNT ON;
    THROW 50001, N'audit.ChangeLog is append-only: entries cannot be updated or deleted.', 1;
END;

BEGIN
    SET NOCOUNT ON;
    THROW 50002, N'auth.AccountStatusChange is append-only: entries cannot be updated or deleted.', 1;
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'auth.ProfilePhoto', COALESCE(i.[UserId], d.[UserId]),
           CASE WHEN d.[UserId] IS NULL THEN 'I' WHEN i.[UserId] IS NULL THEN 'D' ELSE 'U' END,
           IIF(i.[UserId] IS NULL, NULL, CONCAT(N'ContentType=', i.[ContentType], N',SizeBytes=', i.[SizeBytes])),
           @actor, @scope
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[UserId] = i.[UserId];
END;

BEGIN
    SET NOCOUNT ON;

    INSERT [auth].[UserRole] ([UserId], [RoleId])
    SELECT i.[UserId], 6
    FROM inserted AS i
    WHERE NOT EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur WHERE ur.[UserId] = i.[UserId] AND ur.[RoleId] = 6);
END;

BEGIN SET NOCOUNT ON;
DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT); DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
-- Inserts INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ActorUserId], [AccessScope]) SELECT N'auth.User', i.[UserId], 'I', @actor, @scope FROM inserted AS i WHERE NOT EXISTS (SELECT 1 FROM deleted AS d WHERE d.[UserId] = i.[UserId]);
-- Deletes (hard deletes are denied to app roles; logged if an owner ever does one) INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ActorUserId], [AccessScope]) SELECT N'auth.User', d.[UserId], 'D', @actor, @scope FROM deleted AS d WHERE NOT EXISTS (SELECT 1 FROM inserted AS i WHERE i.[UserId] = d.[UserId]);
-- Updates: list the columns whose value actually changed INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope]) SELECT N'auth.User', i.[UserId], 'U', c.[Cols], @actor, @scope FROM inserted AS i JOIN deleted AS d ON d.[UserId] = i.[UserId] CROSS APPLY (SELECT STUFF(CONCAT( CASE WHEN EXISTS (SELECT i.[MobileCountryCode], i.[MobileNumber] EXCEPT SELECT d.[MobileCountryCode], d.[MobileNumber]) THEN N',MobileNumber' END, CASE WHEN EXISTS (SELECT i.[MobileVerifiedAtUtc] EXCEPT SELECT d.[MobileVerifiedAtUtc]) THEN N',MobileVerifiedAtUtc' END, CASE WHEN EXISTS (SELECT i.[Email] EXCEPT SELECT d.[Email]) THEN N',Email' END, CASE WHEN EXISTS (SELECT i.[EmailVerifiedAtUtc] EXCEPT SELECT d.[EmailVerifiedAtUtc]) THEN N',EmailVerifiedAtUtc' END, CASE WHEN EXISTS (SELECT i.[GoogleSubjectId] EXCEPT SELECT d.[GoogleSubjectId]) THEN N',GoogleSubjectId' END, CASE WHEN EXISTS (SELECT i.[FullName] EXCEPT SELECT d.[FullName]) THEN N',FullName' END, CASE WHEN EXISTS (SELECT i.[CountryCode], i.[StateName], i.[City] EXCEPT SELECT d.[CountryCode], d.[StateName], d.[City]) THEN N',Location' END, CASE WHEN EXISTS (SELECT i.[PreferredLanguage] EXCEPT SELECT d.[PreferredLanguage]) THEN N',PreferredLanguage' END, CASE WHEN EXISTS (SELECT i.[IsAdultConfirmed] EXCEPT SELECT d.[IsAdultConfirmed]) THEN N',IsAdultConfirmed' END, CASE WHEN EXISTS (SELECT i.[WhatsAppOptIn] EXCEPT SELECT d.[WhatsAppOptIn]) THEN N',WhatsAppOptIn' END, CASE WHEN EXISTS (SELECT i.[Status] EXCEPT SELECT d.[Status]) THEN N',Status' END, CASE WHEN EXISTS (SELECT i.[ProfileCompletedAtUtc] EXCEPT SELECT d.[ProfileCompletedAtUtc]) THEN N',ProfileCompletedAtUtc' END, CASE WHEN EXISTS (SELECT i.[LastSignInAtUtc] EXCEPT SELECT d.[LastSignInAtUtc]) THEN N',LastSignInAtUtc' END ), 1, 1, N'') AS [Cols]) AS c WHERE c.[Cols] IS NOT NULL; END;

BEGIN
    SET NOCOUNT ON;

    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));

    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'auth.UserPassword', i.[UserId], 'I', IIF(i.[PasswordHash] IS NULL, NULL, N'PasswordHash'), @actor, @scope
    FROM inserted AS i
    WHERE NOT EXISTS (SELECT 1 FROM deleted AS d WHERE d.[UserId] = i.[UserId]);

    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ActorUserId], [AccessScope])
    SELECT N'auth.UserPassword', d.[UserId], 'D', @actor, @scope
    FROM deleted AS d
    WHERE NOT EXISTS (SELECT 1 FROM inserted AS i WHERE i.[UserId] = d.[UserId]);

    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'auth.UserPassword', i.[UserId], 'U', c.[Cols], @actor, @scope
    FROM inserted AS i
    JOIN deleted  AS d ON d.[UserId] = i.[UserId]
    CROSS APPLY (SELECT STUFF(CONCAT(
        IIF(ISNULL(i.[PasswordHash], '') <> ISNULL(d.[PasswordHash], ''),
            IIF(i.[PasswordHash] IS NULL, N',PasswordHash removed', N',PasswordHash changed'), N''),
        IIF(i.[FailedAttempts] <> d.[FailedAttempts], N',FailedAttempts', N''),
        IIF(ISNULL(i.[LockedUntilUtc], '19000101') <> ISNULL(d.[LockedUntilUtc], '19000101'), N',LockedUntilUtc', N'')
    ), 1, 1, N'') AS [Cols]) AS c
    WHERE c.[Cols] IS NOT NULL;
END;

BEGIN
    SET NOCOUNT ON;

    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));

    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'auth.UserRole', i.[UserRoleId], 'I', CONCAT(N'UserId=', i.[UserId], N',RoleId=', i.[RoleId]), @actor, @scope
    FROM inserted AS i
    WHERE NOT EXISTS (SELECT 1 FROM deleted AS d WHERE d.[UserRoleId] = i.[UserRoleId]);

    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'auth.UserRole', d.[UserRoleId], 'D', CONCAT(N'UserId=', d.[UserId], N',RoleId=', d.[RoleId]), @actor, @scope
    FROM deleted AS d
    WHERE NOT EXISTS (SELECT 1 FROM inserted AS i WHERE i.[UserRoleId] = d.[UserRoleId]);

    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'auth.UserRole', i.[UserRoleId], 'U', CONCAT(N'UserId=', i.[UserId], N',RoleId=', i.[RoleId], N',ExpiresAtUtc'), @actor, @scope
    FROM inserted AS i
    JOIN deleted  AS d ON d.[UserRoleId] = i.[UserRoleId];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);

    IF @actor IS NULL OR NOT EXISTS (
        SELECT 1
        FROM [auth].[UserRole] AS ur
        JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
        JOIN [auth].[User] AS u ON u.[UserId] = ur.[UserId]
        WHERE ur.[UserId] = @actor AND r.[RoleCode] = 'SuperAdmin' AND r.[IsActive] = 1 AND u.[Status] = 'Active'
          AND (ur.[ExpiresAtUtc] IS NULL OR ur.[ExpiresAtUtc] > SYSUTCDATETIME()))
        THROW 50010, N'Only a super admin can create staff accounts.', 1;

    DECLARE @roleId SMALLINT = (
        SELECT [RoleId] FROM [auth].[Role]
        WHERE [RoleCode] = @RoleCode AND [IsActive] = 1 AND [RoleCode] IN ('Admin', 'Moderator', 'Support', 'PrivacyOfficer'));
    IF @roleId IS NULL
        THROW 50011, N'That role can''t be given here.', 1;

    SET @Email = LOWER(LTRIM(RTRIM(@Email)));
    IF @Email IS NULL OR @Email NOT LIKE '_%@_%._%' OR LEN(@Email) > 254
        THROW 50012, N'Enter a valid email address.', 1;
    SET @FullName = NULLIF(LTRIM(RTRIM(@FullName)), N'');

    DECLARE @userId BIGINT, @publicId UNIQUEIDENTIFIER, @outcome VARCHAR (20);

    BEGIN TRANSACTION;

    -- Lock the email so two super admins adding the same person at once can't create two accounts
    SELECT @userId = [UserId], @publicId = [PublicId]
    FROM [auth].[User] WITH (UPDLOCK, HOLDLOCK)
    WHERE [Email] = @Email AND [EmailVerifiedAtUtc] IS NOT NULL AND [Status] <> 'Deleted';

    IF @userId IS NULL
    BEGIN
        DECLARE @new TABLE ([UserId] BIGINT, [PublicId] UNIQUEIDENTIFIER);
        -- The super admin vouches for the address; the person can only sign in through it (code or password)
        INSERT [auth].[User] ([SignUpMethod], [Email], [EmailVerifiedAtUtc], [FullName])
        OUTPUT inserted.[UserId], inserted.[PublicId] INTO @new
        VALUES ('Email', @Email, SYSUTCDATETIME(), @FullName);
        SELECT @userId = [UserId], @publicId = [PublicId] FROM @new;

        IF @PasswordHash IS NOT NULL
            INSERT [auth].[UserPassword] ([UserId], [PasswordHash]) VALUES (@userId, @PasswordHash);

        SET @outcome = 'Created';
    END
    ELSE IF EXISTS (SELECT 1 FROM [auth].[UserRole] WHERE [UserId] = @userId AND [RoleId] = @roleId)
        SET @outcome = 'AlreadyHadRole';
    ELSE
        SET @outcome = 'RoleAdded';

    IF @outcome <> 'AlreadyHadRole'
        INSERT [auth].[UserRole] ([UserId], [RoleId], [AssignedByUserId]) VALUES (@userId, @roleId, @actor);

    COMMIT TRANSACTION;

    SELECT @publicId AS [PublicId], @outcome AS [Outcome];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);

    IF @actor IS NULL OR NOT EXISTS (
        SELECT 1
        FROM [auth].[UserRole] AS ur
        JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
        JOIN [auth].[User] AS u ON u.[UserId] = ur.[UserId]
        WHERE ur.[UserId] = @actor AND r.[RoleCode] = 'SuperAdmin' AND r.[IsActive] = 1 AND u.[Status] = 'Active'
          AND (ur.[ExpiresAtUtc] IS NULL OR ur.[ExpiresAtUtc] > SYSUTCDATETIME()))
        THROW 50010, N'Only a super admin can delete staff accounts.', 1;

    BEGIN TRANSACTION;

    DECLARE @userId BIGINT = (
        SELECT u.[UserId] FROM [auth].[User] AS u WITH (UPDLOCK, HOLDLOCK)
        WHERE u.[PublicId] = @PublicId AND u.[Status] <> 'Deleted'
          AND EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
                      WHERE ur.[UserId] = u.[UserId] AND r.[RoleCode] IN ('SuperAdmin', 'Admin', 'Moderator', 'Support', 'PrivacyOfficer')));
    -- Refusals roll back first, so the caller's connection is never left with an open transaction
    IF @userId IS NULL
    BEGIN
        ROLLBACK TRANSACTION;
        THROW 50013, N'That staff member wasn''t found.', 1;
    END
    IF @userId = @actor
    BEGIN
        ROLLBACK TRANSACTION;
        THROW 50014, N'You can''t delete your own account here.', 1;
    END
    IF EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
               WHERE ur.[UserId] = @userId AND r.[RoleCode] = 'SuperAdmin')
    BEGIN
        ROLLBACK TRANSACTION;
        THROW 50015, N'A super admin can''t be deleted here.', 1;
    END

    DELETE [auth].[UserRole] WHERE [UserId] = @userId;
    DELETE [auth].[ProfilePhoto] WHERE [UserId] = @userId;   -- their photo goes with their details

    UPDATE [auth].[UserPassword]
       SET [PasswordHash] = NULL, [FailedAttempts] = 0, [LockedUntilUtc] = NULL, [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [UserId] = @userId;

    UPDATE [auth].[User]
       SET [MobileCountryCode] = NULL, [MobileNumber] = NULL, [MobileVerifiedAtUtc] = NULL,
           [Email] = NULL, [EmailVerifiedAtUtc] = NULL, [GoogleSubjectId] = NULL,
           [FullName] = NULL, [StateName] = NULL, [City] = NULL,
           [WhatsAppOptIn] = 0, [WhatsAppOptInAtUtc] = NULL,
           [Status] = 'Deleted', [DeletedAtUtc] = SYSUTCDATETIME(), [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [UserId] = @userId;

    COMMIT TRANSACTION;

    SELECT @userId AS [UserId];
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL
        THROW 50040, N'Please sign in again.', 1;
    DELETE [auth].[ProfilePhoto] WHERE [UserId] = @me;
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50040, N'Please sign in again.', 1;

    DECLARE @id UNIQUEIDENTIFIER = NEWID();
    BEGIN TRY
        BEGIN TRANSACTION;
        UPDATE [auth].[ProfilePhoto]
           SET [PublicId] = @id, [ContentType] = @ContentType, [Data] = @Data, [SizeBytes] = DATALENGTH(@Data), [UpdatedAtUtc] = SYSUTCDATETIME()
         WHERE [UserId] = @me;
        IF @@ROWCOUNT = 0
            INSERT [auth].[ProfilePhoto] ([UserId], [PublicId], [ContentType], [Data], [SizeBytes])
            VALUES (@me, @id, @ContentType, @Data, DATALENGTH(@Data));
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
    SELECT @id AS [PublicId];
END;

-- The signed-in account's own profile photo. The account is the read-only session-context UserId (never a parameter),
-- and row-level security only lets these touch that account's row. They run as the caller (no EXECUTE AS);
-- removing needs no DELETE permission on the auth schema because the procedure and table share an owner.

-- Saves (adds or replaces) the photo. Returns the new PublicId (a new one every time, so old copies aren't reused).
CREATE PROCEDURE [auth].[usp_SetProfilePhoto]
    @ContentType VARCHAR (20),
    @Data        VARBINARY (MAX)
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @actor IS NULL OR NOT EXISTS (
        SELECT 1
        FROM [auth].[UserRole] AS ur
        JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
        JOIN [auth].[User] AS u ON u.[UserId] = ur.[UserId]
        WHERE ur.[UserId] = @actor AND r.[RoleCode] = 'SuperAdmin' AND r.[IsActive] = 1 AND u.[Status] = 'Active'
          AND (ur.[ExpiresAtUtc] IS NULL OR ur.[ExpiresAtUtc] > SYSUTCDATETIME()))
        THROW 50010, N'Only a super admin can change a staff member''s status.', 1;

    BEGIN TRANSACTION;

    DECLARE @userId BIGINT = (
        SELECT u.[UserId] FROM [auth].[User] AS u WITH (UPDLOCK, HOLDLOCK)
        WHERE u.[PublicId] = @PublicId AND u.[Status] IN ('Active', 'Suspended')
          AND EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
                      WHERE ur.[UserId] = u.[UserId] AND r.[RoleCode] IN ('SuperAdmin', 'Admin', 'Moderator', 'Support', 'PrivacyOfficer')));

    IF @userId IS NULL
    BEGIN ROLLBACK TRANSACTION; THROW 50013, N'That staff member wasn''t found.', 1; END
    IF @userId = @actor
    BEGIN ROLLBACK TRANSACTION; THROW 50014, N'You can''t make your own account inactive.', 1; END
    IF EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
               WHERE ur.[UserId] = @userId AND r.[RoleCode] = 'SuperAdmin')
    BEGIN ROLLBACK TRANSACTION; THROW 50015, N'A super admin''s status can''t be changed here.', 1; END

    UPDATE [auth].[User]
       SET [Status] = IIF(@IsActive = 1, 'Active', 'Suspended'), [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [UserId] = @userId AND [Status] <> IIF(@IsActive = 1, 'Active', 'Suspended');

    COMMIT TRANSACTION;

    SELECT @userId AS [UserId];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @actor IS NULL OR NOT EXISTS (
        SELECT 1
        FROM [auth].[UserRole] AS ur
        JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
        JOIN [auth].[User] AS u ON u.[UserId] = ur.[UserId]
        WHERE ur.[UserId] = @actor AND r.[RoleCode] = 'SuperAdmin' AND r.[IsActive] = 1 AND u.[Status] = 'Active'
          AND (ur.[ExpiresAtUtc] IS NULL OR ur.[ExpiresAtUtc] > SYSUTCDATETIME()))
        THROW 50010, N'Only a super admin can change a visitor''s status.', 1;

    SET @Reason = LTRIM(RTRIM(@Reason));
    IF @Reason IS NULL OR LEN(@Reason) < 10
        THROW 50017, N'Give a reason of at least 10 characters.', 1;

    DECLARE @newStatus VARCHAR (13) = IIF(@IsActive = 1, 'Active', 'Suspended');

    BEGIN TRANSACTION;

    DECLARE @userId BIGINT, @status VARCHAR (13);
    SELECT @userId = u.[UserId], @status = u.[Status]
    FROM [auth].[User] AS u WITH (UPDLOCK, HOLDLOCK)
    WHERE u.[PublicId] = @PublicId AND u.[Status] IN ('Active', 'Suspended')
      AND NOT EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
                      WHERE ur.[UserId] = u.[UserId] AND r.[RoleCode] <> 'Visitor');

    -- Refusals roll back first, so the caller's connection is never left with an open transaction
    IF @userId IS NULL
    BEGIN ROLLBACK TRANSACTION; THROW 50013, N'That visitor wasn''t found.', 1; END
    IF @status = @newStatus
    BEGIN ROLLBACK TRANSACTION; THROW 50018, N'The account already has that status.', 1; END

    UPDATE [auth].[User] SET [Status] = @newStatus, [UpdatedAtUtc] = SYSUTCDATETIME() WHERE [UserId] = @userId;

    INSERT [auth].[AccountStatusChange] ([UserId], [NewStatus], [Reason], [ChangedByUserId])
    VALUES (@userId, @newStatus, @Reason, @actor);

    COMMIT TRANSACTION;

    -- Only the id: personal data stays masked for swp_staff_admin, so the API reads the contact details itself
    SELECT @userId AS [UserId];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @actor IS NULL OR NOT EXISTS (
        SELECT 1
        FROM [auth].[UserRole] AS ur
        JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
        JOIN [auth].[User] AS u ON u.[UserId] = ur.[UserId]
        WHERE ur.[UserId] = @actor AND r.[RoleCode] = 'SuperAdmin' AND r.[IsActive] = 1 AND u.[Status] = 'Active'
          AND (ur.[ExpiresAtUtc] IS NULL OR ur.[ExpiresAtUtc] > SYSUTCDATETIME()))
        THROW 50010, N'Only a super admin can edit staff accounts.', 1;

    DECLARE @roleId SMALLINT = (
        SELECT [RoleId] FROM [auth].[Role]
        WHERE [RoleCode] = @RoleCode AND [IsActive] = 1 AND [RoleCode] IN ('Admin', 'Moderator', 'Support', 'PrivacyOfficer'));
    IF @roleId IS NULL
        THROW 50011, N'That role can''t be given here.', 1;

    SET @Email = LOWER(LTRIM(RTRIM(@Email)));
    IF @Email IS NULL OR @Email NOT LIKE '_%@_%._%' OR LEN(@Email) > 254
        THROW 50012, N'Enter a valid email address.', 1;
    SET @FullName = NULLIF(LTRIM(RTRIM(@FullName)), N'');

    BEGIN TRANSACTION;

    DECLARE @userId BIGINT, @oldEmail NVARCHAR (254);
    SELECT @userId = u.[UserId], @oldEmail = u.[Email]
    FROM [auth].[User] AS u WITH (UPDLOCK, HOLDLOCK)
    WHERE u.[PublicId] = @PublicId AND u.[Status] <> 'Deleted'
      AND EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
                  WHERE ur.[UserId] = u.[UserId] AND r.[RoleCode] IN ('SuperAdmin', 'Admin', 'Moderator', 'Support', 'PrivacyOfficer'));

    -- Refusals roll back first, so the caller's connection is never left with an open transaction
    IF @userId IS NULL
    BEGIN ROLLBACK TRANSACTION; THROW 50013, N'That staff member wasn''t found.', 1; END
    IF @userId = @actor
    BEGIN ROLLBACK TRANSACTION; THROW 50014, N'You can''t edit your own account here.', 1; END
    IF EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
               WHERE ur.[UserId] = @userId AND r.[RoleCode] = 'SuperAdmin')
    BEGIN ROLLBACK TRANSACTION; THROW 50015, N'A super admin can''t be edited here.', 1; END
    IF EXISTS (SELECT 1 FROM [auth].[User] WITH (UPDLOCK, HOLDLOCK)
               WHERE [Email] = @Email AND [EmailVerifiedAtUtc] IS NOT NULL AND [Status] <> 'Deleted' AND [UserId] <> @userId)
    BEGIN ROLLBACK TRANSACTION; THROW 50016, N'That email is already used by another account.', 1; END

    -- Name and sign-in email (a changed email is vouched for by the super admin, as when creating staff)
    UPDATE [auth].[User]
       SET [FullName] = @FullName,
           [Email] = @Email,
           [EmailVerifiedAtUtc] = IIF(ISNULL([Email], N'') = @Email AND [EmailVerifiedAtUtc] IS NOT NULL, [EmailVerifiedAtUtc], SYSUTCDATETIME()),
           [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [UserId] = @userId
       AND (ISNULL([FullName], N'') <> ISNULL(@FullName, N'') OR ISNULL([Email], N'') <> @Email OR [EmailVerifiedAtUtc] IS NULL);

    -- Exactly one staff role: drop the others, add the chosen one
    DECLARE @roleChanged BIT = IIF(EXISTS (SELECT 1 FROM [auth].[UserRole] WHERE [UserId] = @userId AND [RoleId] = @roleId)
        AND NOT EXISTS (SELECT 1 FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
                        WHERE ur.[UserId] = @userId AND ur.[RoleId] <> @roleId AND r.[RoleCode] IN ('Admin', 'Moderator', 'Support', 'PrivacyOfficer')), 0, 1);
    IF @roleChanged = 1
    BEGIN
        DELETE ur FROM [auth].[UserRole] AS ur JOIN [auth].[Role] AS r ON r.[RoleId] = ur.[RoleId]
         WHERE ur.[UserId] = @userId AND ur.[RoleId] <> @roleId AND r.[RoleCode] IN ('Admin', 'Moderator', 'Support', 'PrivacyOfficer');
        IF NOT EXISTS (SELECT 1 FROM [auth].[UserRole] WHERE [UserId] = @userId AND [RoleId] = @roleId)
            INSERT [auth].[UserRole] ([UserId], [RoleId], [AssignedByUserId]) VALUES (@userId, @roleId, @actor);
    END

    -- Optional new password (clears any lock-out)
    IF @PasswordHash IS NOT NULL
    BEGIN
        UPDATE [auth].[UserPassword]
           SET [PasswordHash] = @PasswordHash, [FailedAttempts] = 0, [LockedUntilUtc] = NULL, [UpdatedAtUtc] = SYSUTCDATETIME()
         WHERE [UserId] = @userId;
        IF @@ROWCOUNT = 0
            INSERT [auth].[UserPassword] ([UserId], [PasswordHash]) VALUES (@userId, @PasswordHash);
    END

    COMMIT TRANSACTION;

    SELECT @userId AS [UserId], @roleChanged AS [RoleChanged];
END;

-- Edits a staff account: name, sign-in email, staff role (Admin, Moderator, Support or PrivacyOfficer) and, optionally,
-- sets a new password. Same safety rules as auth.usp_CreateStaffUser / usp_DeleteStaffUser:
--   * the caller must be an active SuperAdmin (id from the read-only session context, never a parameter)
--   * a super admin can't edit themselves here, or another SuperAdmin (that stays with the database owner)
--   * an email already used by another account is refused
--   * every change is recorded in audit.ChangeLog by the table triggers, with the super admin as the actor
-- Returns the account's internal id and whether the role changed (the API then signs them out, so the new role applies
-- at once). Runs as the login-less user swp_staff_admin (see Security\swp_staff_admin.sql).
CREATE PROCEDURE [auth].[usp_UpdateStaffUser]
    @PublicId     UNIQUEIDENTIFIER,
    @Email        NVARCHAR (254),
    @FullName     NVARCHAR (60),
    @RoleCode     VARCHAR (30),
    @PasswordHash VARCHAR (200)       -- made by the API (PBKDF2); NULL = keep the current password
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    DECLARE @prefix VARCHAR (10) = CONCAT('SWP-', YEAR(SYSUTCDATETIME()), '-');
    DECLARE @last INT = (SELECT MAX(TRY_CAST(RIGHT([ReceiptNo], 6) AS INT)) FROM [give].[Donation] WHERE [ReceiptNo] LIKE @prefix + '%');
    RETURN CONCAT(@prefix, RIGHT(CONCAT('000000', ISNULL(@last, 0) + 1), 6));
END;

BEGIN
    SET NOCOUNT ON;
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'give.Campaign', COALESCE(i.[CampaignId], d.[CampaignId]),
           CASE WHEN d.[CampaignId] IS NULL THEN 'I' WHEN i.[CampaignId] IS NULL THEN 'D' ELSE 'U' END,
           CONCAT(N'Status=', COALESCE(i.[Status], d.[Status])),
           TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT), CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20))
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[CampaignId] = i.[CampaignId];
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'give.Donation', COALESCE(i.[DonationId], d.[DonationId]),
           CASE WHEN d.[DonationId] IS NULL THEN 'I' WHEN i.[DonationId] IS NULL THEN 'D' ELSE 'U' END,
           CASE WHEN d.[DonationId] IS NULL THEN CONCAT(N'Method=', i.[Method], N',Amount=', i.[Amount], N',Status=', i.[Status])
                WHEN i.[DonationId] IS NOT NULL AND i.[Status] <> d.[Status] THEN CONCAT(N'Status=', i.[Status], N',was=', d.[Status]) END,
           @actor, @scope
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[DonationId] = i.[DonationId];
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT), @campaign INT = NULL;
    IF @CampaignPublicId IS NOT NULL
    BEGIN
        SET @campaign = (SELECT [CampaignId] FROM [give].[Campaign] WHERE [PublicId] = @CampaignPublicId AND [Status] = 'Active'
                           AND ([EndsAtUtc] IS NULL OR [EndsAtUtc] > SYSUTCDATETIME()));
        IF @campaign IS NULL
            THROW 50061, N'That campaign isn''t taking donations now.', 1;
    END;
    -- Stops a script from filling the table with unpaid donations
    IF (SELECT COUNT(*) FROM [give].[Donation] WHERE [Email] = @Email AND [CreatedAtUtc] > DATEADD(HOUR, -1, SYSUTCDATETIME()) AND [Status] = 'Created') >= 10
        THROW 50062, N'Too many tries. Please wait a little and try again.', 1;
    DECLARE @new TABLE ([PublicId] UNIQUEIDENTIFIER);
    INSERT [give].[Donation] ([CampaignId], [UserId], [Amount], [DonorName], [Email], [Phone], [Pan], [InHonourOf], [Message], [ShowOnWall], [WallName],
        [Method], [GatewayOrderId], [Status])
    OUTPUT inserted.[PublicId] INTO @new
    VALUES (@campaign, @me, @Amount, LTRIM(RTRIM(@DonorName)), LOWER(LTRIM(RTRIM(@Email))), NULLIF(LTRIM(RTRIM(@Phone)), ''), NULLIF(UPPER(LTRIM(RTRIM(@Pan))), ''),
        NULLIF(LTRIM(RTRIM(@InHonourOf)), N''), NULLIF(LTRIM(RTRIM(@Message)), N''), ISNULL(@ShowOnWall, 0), NULLIF(LTRIM(RTRIM(@WallName)), N''),
        'razorpay', @GatewayOrderId, 'Created');
    SELECT [PublicId] FROM @new;
END;

-- A visitor starts an online donation (the API has created the payment gateway's order first). Anyone may give, signed
-- in or not; the signed-in visitor's id is taken from the read-only session context. Status starts as 'Created': it only
-- becomes 'Paid' through give.usp_SetDonationPaid, after the API has verified the gateway's signature.
CREATE PROCEDURE [give].[usp_CreateDonation]
    @CampaignPublicId UNIQUEIDENTIFIER,
    @Amount           DECIMAL (12, 2),
    @DonorName        NVARCHAR (100),
    @Email            NVARCHAR (254),
    @Phone            VARCHAR (20),
    @Pan              CHAR (10),
    @InHonourOf       NVARCHAR (100),
    @Message          NVARCHAR (300),
    @ShowOnWall       BIT,
    @WallName         NVARCHAR (60),
    @GatewayOrderId   VARCHAR (60)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50060, N'Only a super admin or admin can manage campaigns.', 1;
    DECLARE @id INT = (SELECT [CampaignId] FROM [give].[Campaign] WHERE [PublicId] = @PublicId);
    IF @id IS NULL
        THROW 50061, N'That campaign wasn''t found.', 1;
    IF EXISTS (SELECT 1 FROM [give].[Donation] WHERE [CampaignId] = @id)
        THROW 50063, N'This campaign has donations, so it can''t be deleted. Close it instead.', 1;
    DELETE [give].[Campaign] WHERE [CampaignId] = @id;
END;

BEGIN
    SET NOCOUNT ON;
    IF ISNULL(CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20)), N'') <> N'System'
        THROW 50060, N'Only the website can record that.', 1;
    UPDATE [give].[Donation] SET [ReceiptSentAtUtc] = SYSUTCDATETIME() WHERE [PublicId] = @PublicId AND [Status] = 'Paid';
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50060, N'Only a super admin or admin can record donations.', 1;
    IF @Method NOT IN ('cash', 'bank', 'cheque', 'upi')
        THROW 50063, N'Choose how it was paid.', 1;
    DECLARE @campaign INT = NULL;
    IF @CampaignPublicId IS NOT NULL
    BEGIN
        SET @campaign = (SELECT [CampaignId] FROM [give].[Campaign] WHERE [PublicId] = @CampaignPublicId);
        IF @campaign IS NULL THROW 50061, N'That campaign wasn''t found.', 1;
    END;
    DECLARE @new TABLE ([PublicId] UNIQUEIDENTIFIER, [ReceiptNo] VARCHAR (24));
    INSERT [give].[Donation] ([CampaignId], [Amount], [DonorName], [Email], [Phone], [Pan], [InHonourOf], [ShowOnWall], [WallName],
        [Method], [Reference], [Status], [ReceiptNo], [PaidAtUtc], [RecordedByUserId])
    OUTPUT inserted.[PublicId], inserted.[ReceiptNo] INTO @new
    VALUES (@campaign, @Amount, LTRIM(RTRIM(@DonorName)), LOWER(LTRIM(RTRIM(@Email))), NULLIF(LTRIM(RTRIM(@Phone)), ''), NULLIF(UPPER(LTRIM(RTRIM(@Pan))), ''),
        NULLIF(LTRIM(RTRIM(@InHonourOf)), N''), ISNULL(@ShowOnWall, 0), NULLIF(LTRIM(RTRIM(@WallName)), N''),
        @Method, NULLIF(LTRIM(RTRIM(@Reference)), N''), 'Paid', [give].[fn_NextReceiptNo](), ISNULL(@PaidAtUtc, SYSUTCDATETIME()), @actor);
    SELECT [PublicId], [ReceiptNo] FROM @new;
END;

-- Staff record a donation received offline (cash, bank transfer, cheque, UPI to the account): paid straight away, with a
-- receipt number. SuperAdmin or Admin. Returns the public id and receipt number.
CREATE PROCEDURE [give].[usp_RecordOfflineDonation]
    @CampaignPublicId UNIQUEIDENTIFIER,
    @Amount           DECIMAL (12, 2),
    @Method           VARCHAR (10),
    @Reference        NVARCHAR (100),
    @DonorName        NVARCHAR (100),
    @Email            NVARCHAR (254),
    @Phone            VARCHAR (20),
    @Pan              CHAR (10),
    @InHonourOf       NVARCHAR (100),
    @ShowOnWall       BIT,
    @WallName         NVARCHAR (60),
    @PaidAtUtc        DATETIME2 (0)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50060, N'Only a super admin or admin can mark refunds.', 1;
    IF LEN(LTRIM(RTRIM(ISNULL(@Note, N'')))) < 5
        THROW 50063, N'Say why it was refunded (at least 5 characters).', 1;
    UPDATE [give].[Donation] SET [Status] = 'Refunded', [StatusNote] = LTRIM(RTRIM(@Note)), [RecordedByUserId] = @actor
     WHERE [PublicId] = @PublicId AND [Status] = 'Paid';
    IF @@ROWCOUNT = 0
        THROW 50061, N'Only a paid donation can be marked refunded.', 1;
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50060, N'Only a super admin or admin can manage campaigns.', 1;
    SET @Slug = LOWER(LTRIM(RTRIM(@Slug)));
    IF EXISTS (SELECT 1 FROM [give].[Campaign] WHERE [Slug] = @Slug AND (@PublicId IS NULL OR [PublicId] <> @PublicId))
        THROW 50063, N'Another campaign already uses that web address.', 1;
    IF @PublicId IS NULL
    BEGIN
        DECLARE @new TABLE ([PublicId] UNIQUEIDENTIFIER);
        INSERT [give].[Campaign] ([Slug], [Title], [Summary], [Story], [Image], [GoalAmount], [OfflineRaised], [StartsAtUtc], [EndsAtUtc], [Status], [IsFeatured], [SortOrder])
        OUTPUT inserted.[PublicId] INTO @new
        VALUES (@Slug, @Title, @Summary, @Story, @Image, @GoalAmount, ISNULL(@OfflineRaised, 0), @StartsAtUtc, @EndsAtUtc, @Status, @IsFeatured, ISNULL(@SortOrder, 0));
        SELECT [PublicId] FROM @new;
        RETURN;
    END;
    UPDATE [give].[Campaign]
       SET [Slug] = @Slug, [Title] = @Title, [Summary] = @Summary, [Story] = @Story, [Image] = @Image, [GoalAmount] = @GoalAmount,
           [OfflineRaised] = ISNULL(@OfflineRaised, 0), [StartsAtUtc] = @StartsAtUtc, [EndsAtUtc] = @EndsAtUtc, [Status] = @Status,
           [IsFeatured] = @IsFeatured, [SortOrder] = ISNULL(@SortOrder, 0), [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [PublicId] = @PublicId;
    IF @@ROWCOUNT = 0
        THROW 50061, N'That campaign wasn''t found.', 1;
    SELECT @PublicId AS [PublicId];
END;

-- Adds (@PublicId NULL) or changes a campaign. Active SuperAdmin or Admin. Returns its public id.
CREATE PROCEDURE [give].[usp_SaveCampaign]
    @PublicId       UNIQUEIDENTIFIER,
    @Slug           VARCHAR (60),
    @Title          NVARCHAR (120),
    @Summary        NVARCHAR (300),
    @Story          NVARCHAR (4000),
    @Image          VARCHAR (80),
    @GoalAmount     DECIMAL (12, 2),
    @OfflineRaised  DECIMAL (12, 2),
    @StartsAtUtc    DATETIME2 (0),
    @EndsAtUtc      DATETIME2 (0),
    @Status         VARCHAR (10),
    @IsFeatured     BIT,
    @SortOrder      INT
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50060, N'Only a super admin or admin can edit the Support page.', 1;
    IF @LanguageCode NOT IN ('en', 'hi', 'bn', 'ar', 'es', 'fr')
        THROW 50063, N'Choose a language.', 1;
    IF @ContentJson IS NULL
    BEGIN
        DELETE [give].[SupportContent] WHERE [LanguageCode] = @LanguageCode;
        RETURN;
    END;
    IF ISJSON(@ContentJson) <> 1
        THROW 50063, N'The Support page content isn''t valid.', 1;
    UPDATE [give].[SupportContent] SET [ContentJson] = @ContentJson, [UpdatedByUserId] = @actor, [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [LanguageCode] = @LanguageCode;
    IF @@ROWCOUNT = 0
        INSERT [give].[SupportContent] ([LanguageCode], [ContentJson], [UpdatedByUserId]) VALUES (@LanguageCode, @ContentJson, @actor);
END;

BEGIN
    SET NOCOUNT ON;
    IF ISNULL(CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20)), N'') <> N'System'
        THROW 50060, N'Only the payment check can change a donation.', 1;
    UPDATE [give].[Donation] SET [Status] = 'Failed', [StatusNote] = LEFT(REPLACE(REPLACE(@Reason, '<', ''), '>', ''), 300)
     WHERE [GatewayOrderId] = @GatewayOrderId AND [Status] = 'Created';
END;

-- The gateway reported a failed payment (or the visitor closed the checkout). Only from the API's system access;
-- never changes a paid donation.
CREATE PROCEDURE [give].[usp_SetDonationFailed]
    @GatewayOrderId VARCHAR (60),
    @Reason         NVARCHAR (300)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF ISNULL(CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20)), N'') <> N'System'
        THROW 50060, N'Only the payment check can mark a donation paid.', 1;
    DECLARE @id BIGINT, @amount DECIMAL (12, 2), @status VARCHAR (10), @justPaid BIT = 0;
    BEGIN TRANSACTION;
    SELECT @id = [DonationId], @amount = [Amount], @status = [Status] FROM [give].[Donation] WITH (UPDLOCK, HOLDLOCK) WHERE [GatewayOrderId] = @GatewayOrderId;
    IF @id IS NULL BEGIN ROLLBACK; THROW 50061, N'That donation wasn''t found.', 1; END;
    IF @AmountPaid <> @amount BEGIN ROLLBACK; THROW 50063, N'The amount paid doesn''t match the donation.', 1; END;
    IF @status IN ('Created', 'Failed')
    BEGIN
        UPDATE [give].[Donation] SET [Status] = 'Paid', [GatewayPaymentId] = @GatewayPaymentId, [PaidAtUtc] = SYSUTCDATETIME(),
               [ReceiptNo] = [give].[fn_NextReceiptNo](), [StatusNote] = NULL
         WHERE [DonationId] = @id;
        SET @justPaid = 1;
    END;
    COMMIT;
    SELECT [PublicId], [ReceiptNo], [Amount], [DonorName], [Email], [Pan], [InHonourOf], [PaidAtUtc], @justPaid AS [JustPaid],
           (SELECT c.[Title] FROM [give].[Campaign] AS c WHERE c.[CampaignId] = d.[CampaignId]) AS [CampaignTitle]
    FROM [give].[Donation] AS d WHERE [DonationId] = @id;
END;

-- The payment gateway confirmed a payment (the API verified its signature first). Only from the API's system access.
-- Idempotent: the checkout and the webhook may both report the same payment. The amount must match what was ordered.
-- Returns the donation and whether this call just marked it paid (so the receipt email is sent once).
CREATE PROCEDURE [give].[usp_SetDonationPaid]
    @GatewayOrderId   VARCHAR (60),
    @GatewayPaymentId VARCHAR (60),
    @AmountPaid       DECIMAL (12, 2)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    INSERT @r
    SELECT s.[SubmissionId], (SELECT COUNT(*) FROM [selfie].[Candle] AS c WHERE c.[SubmissionId] = s.[SubmissionId])
    FROM [selfie].[Submission] AS s
    WHERE s.[PublicId] = @PublicId AND s.[Status] = 'Approved' AND s.[Kind] = 'memory';
    RETURN;
END;

BEGIN
    INSERT @r
    SELECT s.[StoryId], (SELECT COUNT(*) FROM [selfie].[ParentStoryLove] AS l WHERE l.[StoryId] = s.[StoryId])
    FROM [selfie].[ParentStory] AS s
    WHERE s.[PublicId] = @PublicId AND s.[Status] = 'Approved';
    RETURN;
END;

BEGIN
    INSERT @r
    SELECT s.[SubmissionId], (SELECT COUNT(*) FROM [selfie].[SubmissionLike] AS l WHERE l.[SubmissionId] = s.[SubmissionId])
    FROM [selfie].[Submission] AS s
    WHERE s.[PublicId] = @PublicId AND s.[Status] = 'Approved';
    RETURN;
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'selfie.ParentStory', COALESCE(i.[StoryId], d.[StoryId]),
           CASE WHEN d.[StoryId] IS NULL THEN 'I' WHEN i.[StoryId] IS NULL THEN 'D' ELSE 'U' END,
           CASE WHEN d.[StoryId] IS NULL THEN CONCAT(N'WrittenBy=', i.[WrittenBy])
                WHEN i.[StoryId] IS NOT NULL AND i.[Status] <> d.[Status] THEN CONCAT(N'Status=', i.[Status], N',was=', d.[Status])
                WHEN i.[StoryId] IS NOT NULL AND i.[IsFeatured] <> d.[IsFeatured] THEN CONCAT(N'IsFeatured=', i.[IsFeatured]) END,
           @actor, @scope
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[StoryId] = i.[StoryId];
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'selfie.Submission', COALESCE(i.[SubmissionId], d.[SubmissionId]),
           CASE WHEN d.[SubmissionId] IS NULL THEN 'I' WHEN i.[SubmissionId] IS NULL THEN 'D' ELSE 'U' END,
           CASE WHEN d.[SubmissionId] IS NULL THEN CONCAT(N'Kind=', i.[Kind])
                WHEN i.[SubmissionId] IS NOT NULL AND i.[Status] <> d.[Status] THEN CONCAT(N'Status=', i.[Status], N',was=', d.[Status]) END,
           @actor, @scope
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[SubmissionId] = i.[SubmissionId];
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'selfie.SubmissionFile', COALESCE(i.[FileId], d.[FileId]), IIF(i.[FileId] IS NULL, 'D', 'I'),
           CONCAT(N'Submission=', COALESCE(i.[SubmissionId], d.[SubmissionId]), N',Role=', COALESCE(i.[Role], d.[Role]),
                  IIF(i.[FileId] IS NULL, NULL, CONCAT(N',ContentType=', i.[ContentType], N',SizeBytes=', i.[SizeBytes]))),
           @actor, @scope
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[FileId] = i.[FileId];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50050, N'Please sign in again.', 1;
    SET @Title = NULLIF(LTRIM(RTRIM(@Title)), N'');
    SET @Story = NULLIF(LTRIM(RTRIM(@Story)), N'');
    IF @Title IS NULL OR LEN(@Title) < 3
        THROW 50052, N'Give the story a short title.', 1;
    IF @Story IS NULL OR LEN(@Story) < 40
        THROW 50052, N'Please write a little more of the story (at least 40 characters).', 1;
    -- A few stories a day per account is plenty; this stops a script from filling the database
    IF (SELECT COUNT(*) FROM [selfie].[ParentStory] WHERE [UserId] = @me AND [CreatedAtUtc] > DATEADD(DAY, -1, SYSUTCDATETIME())) >= 5
        THROW 50053, N'You''ve shared 5 stories today. Please try again tomorrow.', 1;

    DECLARE @new TABLE ([StoryId] BIGINT, [PublicId] UNIQUEIDENTIFIER);
    BEGIN TRY
        BEGIN TRANSACTION;
        INSERT [selfie].[ParentStory] ([UserId], [WrittenBy], [ParentRole], [ShownName], [Age], [CountryCode], [StateName], [City],
            [Title], [Story], [Wish], [ConsentedAtUtc])
        OUTPUT inserted.[StoryId], inserted.[PublicId] INTO @new
        VALUES (@me, @WrittenBy, @ParentRole, NULLIF(LTRIM(RTRIM(@ShownName)), N''), @Age, @CountryCode,
            NULLIF(LTRIM(RTRIM(@StateName)), N''), NULLIF(LTRIM(RTRIM(@City)), N''), @Title, @Story, NULLIF(LTRIM(RTRIM(@Wish)), N''),
            SYSUTCDATETIME());

        INSERT [selfie].[ParentStoryFile] ([StoryId], [UserId], [Role], [ContentType], [FileName], [Data], [SizeBytes])
        SELECT n.[StoryId], @me, f.[Role], f.[ContentType], f.[FileName], f.[Data], DATALENGTH(f.[Data])
        FROM @new AS n
        CROSS APPLY (VALUES ('main', @PhotoType, @PhotoName, @PhotoData), ('video', @VideoType, @VideoName, @VideoData),
                            ('voice', @VoiceType, @VoiceName, @VoiceData)) AS f ([Role], [ContentType], [FileName], [Data])
        WHERE f.[Data] IS NOT NULL;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;

    SELECT n.[PublicId], CONCAT('PV-', RIGHT(CONCAT('000000', n.[StoryId]), 6)) AS [Reference] FROM @new AS n;
END;

-- A signed-in visitor shares a parent's story (their own, or one they write with the parent's agreement), with an
-- optional photo, video and voice note. The owner is the session-context UserId (never a parameter); it always starts as
-- 'Pending'. Story and files are saved together or not at all. Runs as the caller (row-level security).
CREATE PROCEDURE [selfie].[usp_CreateParentStory]
    @WrittenBy      VARCHAR (10),
    @ParentRole     VARCHAR (10),
    @ShownName      NVARCHAR (60),     -- NULL: anonymous ("A mother from …")
    @Age            TINYINT,
    @CountryCode    CHAR (2),
    @StateName      NVARCHAR (60),
    @City           NVARCHAR (60),
    @Title          NVARCHAR (120),
    @Story          NVARCHAR (3000),
    @Wish           NVARCHAR (300),
    @PhotoType      VARCHAR (20) = NULL,
    @PhotoData      VARBINARY (MAX) = NULL,
    @PhotoName      NVARCHAR (150) = NULL,
    @VideoType      VARCHAR (20) = NULL,
    @VideoData      VARBINARY (MAX) = NULL,
    @VideoName      NVARCHAR (150) = NULL,
    @VoiceType      VARCHAR (20) = NULL,
    @VoiceData      VARBINARY (MAX) = NULL,
    @VoiceName      NVARCHAR (150) = NULL
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50030, N'Please sign in again.', 1;
    IF @MainData IS NULL AND @VideoData IS NULL
        THROW 50032, N'Add a photo or a video.', 1;
    IF @Kind <> 'family' AND @MainData IS NOT NULL AND @VideoData IS NOT NULL
        THROW 50032, N'Share a photo or a video (only family submissions can have both).', 1;
    IF @SourceData IS NOT NULL AND (@Kind <> 'ai' OR @MainData IS NULL)
        THROW 50032, N'An original photo can only go with an AI-made photo.', 1;
    IF @Kind = 'thennow' AND (@MainData IS NULL OR @ThenData IS NULL OR @VideoData IS NOT NULL)
        THROW 50032, N'Then & Now needs the old photo and the new photo.', 1;
    IF @ThenData IS NOT NULL AND @Kind <> 'thennow'
        THROW 50032, N'An old photo only goes with Then & Now.', 1;
    IF @VoiceData IS NOT NULL AND (@MainData IS NULL OR @VideoData IS NOT NULL OR @Kind = 'family')
        THROW 50032, N'A voice note can only go with a photo or an AI-made photo.', 1;
    -- A few submissions a day per account is plenty; this stops a script from filling the database
    IF (SELECT COUNT(*) FROM [selfie].[Submission] WHERE [UserId] = @me AND [CreatedAtUtc] > DATEADD(DAY, -1, SYSUTCDATETIME())) >= 10
        THROW 50033, N'You''ve shared 10 times today. Please try again tomorrow.', 1;

    DECLARE @new TABLE ([SubmissionId] BIGINT, [PublicId] UNIQUEIDENTIFIER);
    BEGIN TRY
        BEGIN TRANSACTION;
        INSERT [selfie].[Submission] ([UserId], [Kind], [YourName], [ParentName], [Relation], [FamilySize], [Generations], [MemoryYear],
            [CountryCode], [StateName], [City], [IsAdult], [GuardianName], [GuardianMobile], [Message], [ConsentedAtUtc], [ThenYear], [NowYear])
        OUTPUT inserted.[SubmissionId], inserted.[PublicId] INTO @new
        VALUES (@me, @Kind, @YourName, @ParentName, @Relation, @FamilySize, @Generations, @MemoryYear,
            @CountryCode, @StateName, @City, @IsAdult, @GuardianName, @GuardianMobile, @Message, SYSUTCDATETIME(),
            IIF(@Kind = 'thennow', @ThenYear, NULL), IIF(@Kind = 'thennow', @NowYear, NULL));

        INSERT [selfie].[SubmissionFile] ([SubmissionId], [UserId], [Role], [ContentType], [FileName], [Data], [SizeBytes])
        SELECT n.[SubmissionId], @me, f.[Role], f.[ContentType], f.[FileName], f.[Data], DATALENGTH(f.[Data])
        FROM @new AS n
        CROSS APPLY (VALUES ('main', @MainType, @MainName, @MainData), ('source', @SourceType, @SourceName, @SourceData),
                            ('video', @VideoType, @VideoName, @VideoData), ('voice', @VoiceType, @VoiceName, @VoiceData),
                            ('then', @ThenType, @ThenName, @ThenData)) AS f ([Role], [ContentType], [FileName], [Data])
        WHERE f.[Data] IS NOT NULL;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;   -- never leave the caller with an open transaction
        THROW;
    END CATCH;

    SELECT n.[PublicId], CONCAT('SWP-', RIGHT(CONCAT('000000', n.[SubmissionId]), 6)) AS [Reference] FROM @new AS n;
END;

-- Selfie submissions: the only ways the website can create or review them. Errors 50030-50039 are shown to the user.

-- A signed-in visitor shares a photo and / or video (and, with a photo, an optional voice note). The owner is the read-only session-context UserId (never a
-- parameter) and the status always starts as 'Pending'. Submission and files are saved together or not at all.
-- Runs as the caller: row-level security only lets it write rows for that account.
CREATE PROCEDURE [selfie].[usp_CreateSubmission]
    @Kind           VARCHAR (10),
    @YourName       NVARCHAR (60),
    @ParentName     NVARCHAR (60),
    @Relation       VARCHAR (20),
    @FamilySize     VARCHAR (5),
    @Generations    VARCHAR (2),
    @MemoryYear     SMALLINT,
    @CountryCode    CHAR (2),
    @StateName      NVARCHAR (60),
    @City           NVARCHAR (60),
    @IsAdult        BIT,
    @GuardianName   NVARCHAR (60),
    @GuardianMobile VARCHAR (20),
    @Message        NVARCHAR (300),
    @MainType       VARCHAR (20),      -- photo (NULL when only a video is shared)
    @MainData       VARBINARY (MAX),
    @MainName       NVARCHAR (150),
    @SourceType     VARCHAR (20),      -- 'ai' only, optional
    @SourceData     VARBINARY (MAX),
    @SourceName     NVARCHAR (150),
    @VideoType      VARCHAR (20),      -- video (NULL when only a photo is shared)
    @VideoData      VARBINARY (MAX),
    @VideoName      NVARCHAR (150),
    @VoiceType      VARCHAR (20) = NULL,   -- optional voice note: only with a photo, not with a video or a family share
    @VoiceData      VARBINARY (MAX) = NULL,
    @VoiceName      NVARCHAR (150) = NULL,
    @ThenType       VARCHAR (20) = NULL,   -- 'thennow' only: the old photo (the main photo is the same picture today)
    @ThenData       VARBINARY (MAX) = NULL,
    @ThenName       NVARCHAR (150) = NULL,
    @ThenYear       SMALLINT = NULL,
    @NowYear        SMALLINT = NULL
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50034, N'Only a super admin or admin can manage contests.', 1;
    IF EXISTS (SELECT 1 FROM [selfie].[Contest] WHERE [PublicId] = @PublicId AND [ClosedAtUtc] IS NOT NULL)
        THROW 50035, N'That contest has already been decided.', 1;
    DELETE [selfie].[Contest] WHERE [PublicId] = @PublicId AND [Kind] = 'festival';
    IF @@ROWCOUNT = 0
        THROW 50031, N'That contest wasn''t found.', 1;
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL
        THROW 50030, N'Please sign in again.', 1;
    DELETE [selfie].[FamilyDate] WHERE [PublicId] = @PublicId AND [UserId] = @me;
    IF @@ROWCOUNT = 0
        THROW 50031, N'That date wasn''t found.', 1;
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL
        THROW 50030, N'Please sign in again.', 1;
    DELETE [selfie].[Candle] WHERE [UserId] = @me;       -- candles they lit on the Memory Wall
    DELETE [selfie].[SubmissionLike] WHERE [UserId] = @me;   -- likes they gave
    DELETE [selfie].[FamilyDate] WHERE [UserId] = @me;   -- family dates and reminder choices / history
    DELETE [selfie].[ReminderSetting] WHERE [UserId] = @me;
    DELETE [selfie].[ReminderLog] WHERE [UserId] = @me;
    UPDATE [selfie].[FamilyAlbum] SET [CreatedByUserId] = NULL WHERE [CreatedByUserId] = @me;   -- family albums they started stay for the others
    DELETE [selfie].[Submission] WHERE [UserId] = @me;   -- files and candles on them go too (ON DELETE CASCADE), and their place in family albums
    DELETE a FROM [selfie].[FamilyAlbum] AS a WHERE NOT EXISTS (SELECT 1 FROM [selfie].[AlbumSubmission] AS x WHERE x.[AlbumId] = a.[AlbumId]);   -- albums nobody is left in
    DELETE [selfie].[ParentStoryLove] WHERE [UserId] = @me;   -- Parents' Voices: love they sent, and the stories they shared
    DELETE [selfie].[ParentStory] WHERE [UserId] = @me;       -- (their files and the love on them go too)
    DELETE [selfie].[GratitudeCheckIn] WHERE [UserId] = @me;  -- gratitude streak
    DELETE [selfie].[Profile] WHERE [UserId] = @me;           -- public profile
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50070, N'Please sign in again.', 1;
    DECLARE @today DATE = CAST(DATEADD(MINUTE, 330, SYSUTCDATETIME()) AS DATE);   -- India time
    IF @WeekStart > @today OR @WeekStart < DATEADD(DAY, -13, @today)
        THROW 50072, N'Only this week can be marked.', 1;
    SET @Note = NULLIF(LTRIM(RTRIM(@Note)), N'');
    UPDATE [selfie].[GratitudeCheckIn] SET [Kind] = @Kind, [Note] = @Note WHERE [UserId] = @me AND [WeekStart] = @WeekStart;
    IF @@ROWCOUNT = 0
        INSERT [selfie].[GratitudeCheckIn] ([UserId], [WeekStart], [Kind], [Note]) VALUES (@me, @WeekStart, @Kind, @Note);
END;

-- Gratitude streaks and public profiles: a visitor's own rows only (session-context UserId; row-level security).
-- Errors 50070-50079 are shown to the user.

-- "This week I called / visited / took a selfie / sent a message". @WeekStart is this week's Monday (India time,
-- worked out by the API); only this week or last week (a late Sunday check-in) can be marked — no filling in old weeks.
CREATE PROCEDURE [selfie].[usp_GratitudeCheckIn]
    @WeekStart DATE,
    @Kind      VARCHAR (10),
    @Note      NVARCHAR (140)
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50080, N'Please sign in again.', 1;
    DECLARE @album BIGINT = (SELECT [AlbumId] FROM [selfie].[FamilyAlbum] WHERE [InviteCode] = LOWER(@InviteCode));
    IF @album IS NULL
        THROW 50083, N'This invite link doesn''t work any more. Ask for a new one.', 1;
    DECLARE @sub BIGINT, @kind VARCHAR (10), @status VARCHAR (10);
    SELECT @sub = [SubmissionId], @kind = [Kind], @status = [Status] FROM [selfie].[Submission] WHERE [PublicId] = @SelfiePublicId AND [UserId] = @me;
    IF @sub IS NULL OR @status = 'Rejected'
        THROW 50081, N'Choose one of your own selfies.', 1;
    IF @kind NOT IN ('real', 'ai', 'thennow', 'memory')
        THROW 50082, N'Only a selfie with your parent can go in a family album.', 1;
    DECLARE @current BIGINT = (SELECT [AlbumId] FROM [selfie].[AlbumSubmission] WHERE [SubmissionId] = @sub);
    IF @current IS NOT NULL AND @current <> @album
        THROW 50084, N'This selfie is already in another family album.', 1;
    IF @current IS NULL
    BEGIN
        IF (SELECT COUNT(*) FROM [selfie].[AlbumSubmission] WHERE [AlbumId] = @album) >= 60
            THROW 50085, N'This family album is full.', 1;
        INSERT [selfie].[AlbumSubmission] ([AlbumId], [SubmissionId]) VALUES (@album, @sub);
    END;
    SELECT [PublicId] FROM [selfie].[FamilyAlbum] WHERE [AlbumId] = @album;
END;

-- Adds the visitor's selfie to the album of an invite link. Returns the album's PublicId.
CREATE PROCEDURE [selfie].[usp_JoinAlbum]
    @InviteCode     VARCHAR (12),
    @SelfiePublicId UNIQUEIDENTIFIER
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL
        THROW 50080, N'Please sign in again.', 1;
    DECLARE @sub BIGINT = (SELECT [SubmissionId] FROM [selfie].[Submission] WHERE [PublicId] = @SelfiePublicId AND [UserId] = @me);
    IF @sub IS NULL
        THROW 50081, N'Choose one of your own selfies.', 1;
    DECLARE @album BIGINT = (SELECT [AlbumId] FROM [selfie].[AlbumSubmission] WHERE [SubmissionId] = @sub);
    DELETE [selfie].[AlbumSubmission] WHERE [SubmissionId] = @sub;
    IF @album IS NOT NULL AND NOT EXISTS (SELECT 1 FROM [selfie].[AlbumSubmission] WHERE [AlbumId] = @album)
        DELETE [selfie].[FamilyAlbum] WHERE [AlbumId] = @album;
END;

BEGIN
    SET NOCOUNT ON;
    IF ISNULL(CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20)), N'') <> N'System'
        THROW 50034, N'Only the reminder job can log reminders.', 1;
    IF @Release = 1
    BEGIN
        DELETE [selfie].[ReminderLog] WHERE [UserId] = @UserId AND [Kind] = @Kind AND [RefId] = @RefId AND [ForDate] = @ForDate;
        SELECT CAST(0 AS BIT) AS [Claimed];
        RETURN;
    END;
    BEGIN TRY
        INSERT [selfie].[ReminderLog] ([UserId], [Kind], [RefId], [ForDate]) VALUES (@UserId, @Kind, @RefId, @ForDate);
        SELECT CAST(1 AS BIT) AS [Claimed];
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() IN (2601, 2627) SELECT CAST(0 AS BIT) AS [Claimed];   -- already sent (or being sent)
        ELSE THROW;
    END CATCH;
END;

-- The background reminder job claims a reminder before sending it (System scope only). Returns 1 when it was claimed now
-- (send it), 0 when it was already sent. @Release = 1 gives a claim back when the email couldn't be sent (tried again later).
CREATE PROCEDURE [selfie].[usp_LogReminder]
    @UserId  BIGINT,
    @Kind    VARCHAR (10),
    @RefId   BIGINT,
    @ForDate DATE,
    @Release BIT = 0
AS

BEGIN
    SET NOCOUNT ON;
    IF ISNULL(CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20)), N'') <> N'System'
        THROW 50034, N'Only the contest job can do this.', 1;
    UPDATE [selfie].[Contest] SET [WinnerNotifiedAtUtc] = SYSUTCDATETIME() WHERE [PublicId] = @PublicId AND [WinnerSubmissionId] IS NOT NULL;
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin', 'Moderator'))
        THROW 50054, N'Only a super admin, admin or moderator can review stories.', 1;
    IF @Status NOT IN ('Approved', 'Rejected', 'Pending')
        THROW 50052, N'Choose approve or reject.', 1;
    SET @Note = NULLIF(LTRIM(RTRIM(@Note)), N'');
    IF @Status = 'Rejected' AND (@Note IS NULL OR LEN(@Note) < 5)
        THROW 50052, N'Give a reason (at least 5 characters) when rejecting.', 1;
    IF @Featured = 1 AND @Status <> 'Approved'
        THROW 50052, N'Only an approved story can be featured.', 1;
    IF NOT EXISTS (SELECT 1 FROM [selfie].[ParentStory] WHERE [PublicId] = @PublicId)
        THROW 50051, N'That story wasn''t found.', 1;

    UPDATE [selfie].[ParentStory]
       SET [Status] = @Status,
           [ReviewNote] = IIF(@Status = 'Pending', NULL, @Note),
           [ReviewedByUserId] = IIF(@Status = 'Pending', NULL, @actor),
           [ReviewedAtUtc] = IIF(@Status = 'Pending', NULL, SYSUTCDATETIME()),
           [IsFeatured] = IIF(@Status = 'Approved', COALESCE(@Featured, [IsFeatured]), 0)
     WHERE [PublicId] = @PublicId;

    SELECT [UserId], CONCAT('PV-', RIGHT(CONCAT('000000', [StoryId]), 6)) AS [Reference] FROM [selfie].[ParentStory] WHERE [PublicId] = @PublicId;
END;

-- Staff approve / reject a parent's story (or put it back to pending), and feature it at the top of Parents' Voices.
-- Super admins, admins and moderators; the role is checked here again.
CREATE PROCEDURE [selfie].[usp_ReviewParentStory]
    @PublicId UNIQUEIDENTIFIER,
    @Status   VARCHAR (10),
    @Note     NVARCHAR (300),
    @Featured BIT = NULL          -- NULL: leave as it is
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin', 'Moderator'))
        THROW 50034, N'Only a super admin, admin or moderator can review submissions.', 1;
    IF @Status NOT IN ('Approved', 'Rejected', 'Pending')
        THROW 50032, N'Choose approve or reject.', 1;
    SET @Note = NULLIF(LTRIM(RTRIM(@Note)), N'');
    IF @Status = 'Rejected' AND (@Note IS NULL OR LEN(@Note) < 5)
        THROW 50032, N'Give a reason (at least 5 characters) when rejecting.', 1;
    IF NOT EXISTS (SELECT 1 FROM [selfie].[Submission] WHERE [PublicId] = @PublicId)
        THROW 50031, N'That submission wasn''t found.', 1;

    UPDATE [selfie].[Submission]
       SET [Status] = @Status,
           [ReviewNote] = IIF(@Status = 'Pending', NULL, @Note),
           [ReviewedByUserId] = IIF(@Status = 'Pending', NULL, @actor),
           [ReviewedAtUtc] = IIF(@Status = 'Pending', NULL, SYSUTCDATETIME()),
           -- no longer approved: no longer featured
           [IsFeatured] = IIF(@Status = 'Approved', [IsFeatured], 0),
           [FeaturedAtUtc] = IIF(@Status = 'Approved', [FeaturedAtUtc], NULL)
     WHERE [PublicId] = @PublicId;

    SELECT [UserId], CONCAT('SWP-', RIGHT(CONCAT('000000', [SubmissionId]), 6)) AS [Reference] FROM [selfie].[Submission] WHERE [PublicId] = @PublicId;
END;

-- Staff approve or reject a submission (a reason of at least 5 characters is needed to reject). A decision can be changed.
-- The caller must be an active SuperAdmin, Admin or Moderator (id from the read-only session context).
-- Runs as the login-less user swp_staff_admin, so it can update a row that belongs to the visitor.
-- Returns the owner's id and the submission's reference, so the API can tell the visitor.
CREATE PROCEDURE [selfie].[usp_ReviewSubmission]
    @PublicId UNIQUEIDENTIFIER,
    @Status   VARCHAR (10),
    @Note     NVARCHAR (300)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF ISNULL(CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20)), N'') <> N'System'
        THROW 50034, N'Only the contest job can run contests.', 1;
    SET @Now = ISNULL(@Now, SYSUTCDATETIME());

    -- This week's contest (Monday 00:00 UTC; 1900-01-01 was a Monday)
    DECLARE @monday DATETIME2 (0) = DATEADD(DAY, (DATEDIFF(DAY, '19000101', @Now) / 7) * 7, CAST('19000101' AS DATETIME2 (0)));
    IF NOT EXISTS (SELECT 1 FROM [selfie].[Contest] WHERE [Kind] = 'week' AND [StartsAtUtc] = @monday)
        INSERT [selfie].[Contest] ([Kind], [Title], [StartsAtUtc], [EndsAtUtc]) VALUES ('week', N'Photo of the Week', @monday, DATEADD(DAY, 7, @monday));

    -- Decide ended contests
    DECLARE @id BIGINT, @start DATETIME2 (0), @end DATETIME2 (0), @winner BIGINT, @likes INT;
    DECLARE ended CURSOR LOCAL FAST_FORWARD FOR
        SELECT [ContestId], [StartsAtUtc], [EndsAtUtc] FROM [selfie].[Contest] WHERE [ClosedAtUtc] IS NULL AND [EndsAtUtc] <= @Now ORDER BY [EndsAtUtc];
    OPEN ended;
    FETCH NEXT FROM ended INTO @id, @start, @end;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SELECT @winner = NULL, @likes = NULL;
        SELECT TOP (1) @winner = s.[SubmissionId], @likes = COUNT(l.[UserId])
        FROM [selfie].[Submission] AS s
        JOIN [selfie].[SubmissionLike] AS l ON l.[SubmissionId] = s.[SubmissionId] AND l.[CreatedAtUtc] < @end AND l.[UserId] <> s.[UserId]
        WHERE s.[Status] = 'Approved' AND s.[Kind] IN ('real', 'ai', 'family', 'thennow')
          AND s.[ReviewedAtUtc] >= @start AND s.[ReviewedAtUtc] < @end
          AND EXISTS (SELECT 1 FROM [selfie].[SubmissionFile] AS f WHERE f.[SubmissionId] = s.[SubmissionId] AND f.[Role] = 'main')
        GROUP BY s.[SubmissionId], s.[ReviewedAtUtc]
        ORDER BY COUNT(l.[UserId]) DESC, s.[ReviewedAtUtc], s.[SubmissionId];
        UPDATE [selfie].[Contest] SET [WinnerSubmissionId] = @winner, [WinnerLikes] = @likes, [ClosedAtUtc] = SYSUTCDATETIME() WHERE [ContestId] = @id;
        FETCH NEXT FROM ended INTO @id, @start, @end;
    END;
    CLOSE ended;
    DEALLOCATE ended;
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50034, N'Only a super admin or admin can manage contests.', 1;
    SET @Title = NULLIF(LTRIM(RTRIM(@Title)), N'');
    IF @Title IS NULL OR @StartsAtUtc IS NULL OR @EndsAtUtc IS NULL OR @EndsAtUtc <= @StartsAtUtc
        THROW 50032, N'Give the contest a name, and an end after its start.', 1;
    IF DATEDIFF(DAY, @StartsAtUtc, @EndsAtUtc) > 31
        THROW 50032, N'A contest can last up to 31 days.', 1;
    IF @PublicId IS NULL
    BEGIN
        DECLARE @new TABLE ([PublicId] UNIQUEIDENTIFIER);
        INSERT [selfie].[Contest] ([Kind], [Title], [StartsAtUtc], [EndsAtUtc], [CreatedByUserId])
        OUTPUT inserted.[PublicId] INTO @new
        VALUES ('festival', @Title, @StartsAtUtc, @EndsAtUtc, @actor);
        SELECT [PublicId] FROM @new;
        RETURN;
    END;
    IF NOT EXISTS (SELECT 1 FROM [selfie].[Contest] WHERE [PublicId] = @PublicId AND [Kind] = 'festival')
        THROW 50031, N'That contest wasn''t found.', 1;
    IF EXISTS (SELECT 1 FROM [selfie].[Contest] WHERE [PublicId] = @PublicId AND [ClosedAtUtc] IS NOT NULL)
        THROW 50035, N'That contest has already been decided.', 1;
    UPDATE [selfie].[Contest] SET [Title] = @Title, [StartsAtUtc] = @StartsAtUtc, [EndsAtUtc] = @EndsAtUtc WHERE [PublicId] = @PublicId;
    SELECT @PublicId AS [PublicId];
END;

-- Photo of the Week / festival contests. Errors 50030-50039 are shown to the user.

-- A super admin / admin adds (@PublicId NULL) or changes a festival contest, e.g. 'Diwali 2026', 1–8 November.
-- A contest that has already been decided can't be changed. Runs as swp_staff_admin; returns the contest's public id.
CREATE PROCEDURE [selfie].[usp_SaveContest]
    @PublicId    UNIQUEIDENTIFIER,
    @Title       NVARCHAR (80),
    @StartsAtUtc DATETIME2 (0),
    @EndsAtUtc   DATETIME2 (0)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50030, N'Please sign in again.', 1;
    SET @Name = NULLIF(LTRIM(RTRIM(@Name)), N'');
    IF @Name IS NULL
        THROW 50032, N'Add their name.', 1;
    IF @DateYear IS NOT NULL AND @DateYear > YEAR(SYSUTCDATETIME())
        THROW 50032, N'The year can''t be in the future.', 1;
    IF @PublicId IS NULL
    BEGIN
        IF (SELECT COUNT(*) FROM [selfie].[FamilyDate] WHERE [UserId] = @me) >= 20
            THROW 50039, N'You can save up to 20 family dates.', 1;
        DECLARE @new TABLE ([PublicId] UNIQUEIDENTIFIER);
        INSERT [selfie].[FamilyDate] ([UserId], [Name], [Relation], [Occasion], [DateMonth], [DateDay], [DateYear])
        OUTPUT inserted.[PublicId] INTO @new
        VALUES (@me, @Name, @Relation, @Occasion, @DateMonth, @DateDay, @DateYear);
        SELECT [PublicId] FROM @new;
        RETURN;
    END;
    UPDATE [selfie].[FamilyDate]
       SET [Name] = @Name, [Relation] = @Relation, [Occasion] = @Occasion, [DateMonth] = @DateMonth, [DateDay] = @DateDay,
           [DateYear] = @DateYear, [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [PublicId] = @PublicId AND [UserId] = @me;
    IF @@ROWCOUNT = 0
        THROW 50031, N'That date wasn''t found.', 1;
    SELECT @PublicId AS [PublicId];
END;

-- A signed-in visitor adds (@PublicId NULL) or changes one of their family dates. Up to 20 per account.
-- Returns the date's public id.
CREATE PROCEDURE [selfie].[usp_SaveFamilyDate]
    @PublicId  UNIQUEIDENTIFIER,
    @Name      NVARCHAR (60),
    @Relation  VARCHAR (20),
    @Occasion  VARCHAR (12),
    @DateMonth TINYINT,
    @DateDay   TINYINT,
    @DateYear  SMALLINT
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50070, N'Please sign in again.', 1;
    SET @Handle = LOWER(LTRIM(RTRIM(@Handle)));
    IF @Handle IN ('admin', 'staff', 'support', 'help', 'about', 'selfie', 'selfies', 'parents', 'login', 'account', 'me', 'api', 'www', 'team', 'official')
        THROW 50073, N'That address is reserved. Please choose another.', 1;
    -- Another visitor's profile is invisible to this account (row-level security), so ask through the unique key
    BEGIN TRY
        UPDATE [selfie].[Profile] SET [Handle] = @Handle, [IsPublic] = @IsPublic, [DisplayName] = LTRIM(RTRIM(@DisplayName)),
               [Bio] = NULLIF(LTRIM(RTRIM(@Bio)), N''), [ShowStreak] = @ShowStreak, [UpdatedAtUtc] = SYSUTCDATETIME()
         WHERE [UserId] = @me;
        IF @@ROWCOUNT = 0
            INSERT [selfie].[Profile] ([UserId], [Handle], [IsPublic], [DisplayName], [Bio], [ShowStreak])
            VALUES (@me, @Handle, @IsPublic, LTRIM(RTRIM(@DisplayName)), NULLIF(LTRIM(RTRIM(@Bio)), N''), @ShowStreak);
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() IN (2601, 2627) THROW 50073, N'That address is taken. Please choose another.', 1;
        THROW;
    END CATCH;
END;

-- Creates or changes the visitor's public profile. The address (handle) must be free; a few words are reserved.
CREATE PROCEDURE [selfie].[usp_SaveMyProfile]
    @Handle      VARCHAR (30),
    @IsPublic    BIT,
    @DisplayName NVARCHAR (60),
    @Bio         NVARCHAR (160),
    @ShowStreak  BIT
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50030, N'Please sign in again.', 1;
    -- The tribute belongs to someone else, so look it up in a way row-level security allows: through the public view of it
    DECLARE @id BIGINT = (SELECT [SubmissionId] FROM [selfie].[fn_ApprovedMemory](@PublicId));
    IF @id IS NULL
        THROW 50036, N'That tribute isn''t on the Memory Wall.', 1;
    IF @Lit = 1 AND NOT EXISTS (SELECT 1 FROM [selfie].[Candle] WHERE [SubmissionId] = @id AND [UserId] = @me)
        INSERT [selfie].[Candle] ([SubmissionId], [UserId]) VALUES (@id, @me);
    IF @Lit = 0
        DELETE [selfie].[Candle] WHERE [SubmissionId] = @id AND [UserId] = @me;
    SELECT [Candles] FROM [selfie].[fn_ApprovedMemory](@PublicId);
END;

-- A signed-in visitor lights (or puts out) their candle on an approved "in loving memory" tribute.
-- Their own candle only (session-context UserId; row-level security). Returns the tribute's candle count.
CREATE PROCEDURE [selfie].[usp_SetCandle]
    @PublicId UNIQUEIDENTIFIER,
    @Lit      BIT
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin', 'Moderator'))
        THROW 50034, N'Only a super admin, admin or moderator can feature submissions.', 1;
    IF NOT EXISTS (SELECT 1 FROM [selfie].[Submission] WHERE [PublicId] = @PublicId)
        THROW 50031, N'That submission wasn''t found.', 1;
    IF @IsFeatured = 1 AND NOT EXISTS (SELECT 1 FROM [selfie].[Submission] WHERE [PublicId] = @PublicId AND [Status] = 'Approved')
        THROW 50035, N'Only an approved submission can be featured.', 1;
    UPDATE [selfie].[Submission]
       SET [IsFeatured] = @IsFeatured, [FeaturedAtUtc] = IIF(@IsFeatured = 1, ISNULL([FeaturedAtUtc], SYSUTCDATETIME()), NULL)
     WHERE [PublicId] = @PublicId;
END;

-- Staff feature (or unfeature) an approved submission for Featured Stories. Same reviewers as usp_ReviewSubmission.
CREATE PROCEDURE [selfie].[usp_SetFeatured]
    @PublicId   UNIQUEIDENTIFIER,
    @IsFeatured BIT
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50030, N'Please sign in again.', 1;
    -- The selfie belongs to someone else, so look it up in a way row-level security allows: through its public view
    DECLARE @id BIGINT = (SELECT [SubmissionId] FROM [selfie].[fn_ApprovedSubmission](@PublicId));
    IF @id IS NULL
        THROW 50031, N'That selfie isn''t in the gallery.', 1;
    IF @Liked = 1 AND NOT EXISTS (SELECT 1 FROM [selfie].[SubmissionLike] WHERE [SubmissionId] = @id AND [UserId] = @me)
        INSERT [selfie].[SubmissionLike] ([SubmissionId], [UserId]) VALUES (@id, @me);
    IF @Liked = 0
        DELETE [selfie].[SubmissionLike] WHERE [SubmissionId] = @id AND [UserId] = @me;
    SELECT [Likes] FROM [selfie].[fn_ApprovedSubmission](@PublicId);
END;

-- Bringing visitors back: likes, family date reminders and the reminder job's log. Errors 50030-50039 are shown to the user.

-- A signed-in visitor likes (or unlikes) an approved selfie / photo frame. Their own like only (session-context UserId;
-- row-level security). Returns the submission's like count.
CREATE PROCEDURE [selfie].[usp_SetLike]
    @PublicId UNIQUEIDENTIFIER,
    @Liked    BIT
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50050, N'Please sign in again.', 1;
    DECLARE @id BIGINT = (SELECT [StoryId] FROM [selfie].[fn_ApprovedParentStory](@PublicId));
    IF @id IS NULL
        THROW 50051, N'That story isn''t on Parents'' Voices.', 1;
    IF @Loved = 1 AND NOT EXISTS (SELECT 1 FROM [selfie].[ParentStoryLove] WHERE [StoryId] = @id AND [UserId] = @me)
        INSERT [selfie].[ParentStoryLove] ([StoryId], [UserId]) VALUES (@id, @me);
    IF @Loved = 0
        DELETE [selfie].[ParentStoryLove] WHERE [StoryId] = @id AND [UserId] = @me;
    SELECT [Loves] FROM [selfie].[fn_ApprovedParentStory](@PublicId);
END;

-- A signed-in visitor sends (or takes back) their love on an approved story. Their own row only (row-level security).
-- Returns the story's love count.
CREATE PROCEDURE [selfie].[usp_SetParentStoryLove]
    @PublicId UNIQUEIDENTIFIER,
    @Loved    BIT
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL
        THROW 50030, N'Please sign in again.', 1;
    UPDATE [selfie].[ReminderSetting]
       SET [EmailReminders] = @EmailReminders, [ThenNowNudges] = @ThenNowNudges, [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [UserId] = @me;
    IF @@ROWCOUNT = 0
        INSERT [selfie].[ReminderSetting] ([UserId], [EmailReminders], [ThenNowNudges]) VALUES (@me, @EmailReminders, @ThenNowNudges);
END;

-- A visitor's reminder choices: from My account (signed in), or from the "switch off" link in a reminder email (the API
-- checks the link's signature and then calls this for that account).
CREATE PROCEDURE [selfie].[usp_SetReminderSettings]
    @EmailReminders BIT,
    @ThenNowNudges  BIT
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL
        THROW 50070, N'Please sign in again.', 1;
    UPDATE [selfie].[ReminderSetting] SET [StreakNudges] = @On, [UpdatedAtUtc] = SYSUTCDATETIME() WHERE [UserId] = @me;
    IF @@ROWCOUNT = 0
        INSERT [selfie].[ReminderSetting] ([UserId], [EmailReminders], [ThenNowNudges], [StreakNudges]) VALUES (@me, 1, 1, @On);
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50030, N'Please sign in again.', 1;
    IF @PictureData IS NULL
        THROW 50032, N'Add the framed picture.', 1;
    DECLARE @source BIGINT = (
        SELECT s.[SubmissionId] FROM [selfie].[Submission] AS s
        WHERE s.[PublicId] = @SourcePublicId AND s.[UserId] = @me AND s.[Status] = 'Approved' AND s.[Kind] <> 'frame'
          AND EXISTS (SELECT 1 FROM [selfie].[SubmissionFile] AS f WHERE f.[SubmissionId] = s.[SubmissionId] AND f.[Role] = 'main'));
    IF @source IS NULL
        THROW 50037, N'Only your own approved photo selfie can be shared in a frame.', 1;
    IF EXISTS (SELECT 1 FROM [selfie].[Submission] WHERE [SourceSubmissionId] = @source AND [FrameStyle] = @FrameStyle AND [Status] IN ('Pending', 'Approved'))
        THROW 50038, N'You''ve already shared this frame.', 1;
    IF (SELECT COUNT(*) FROM [selfie].[Submission] WHERE [UserId] = @me AND [CreatedAtUtc] > DATEADD(DAY, -1, SYSUTCDATETIME())) >= 10
        THROW 50033, N'You''ve shared 10 times today. Please try again tomorrow.', 1;

    DECLARE @auto BIT = IIF(EXISTS (SELECT 1 FROM [site].[Setting] WHERE [SettingKey] = 'frames.auto-approve' AND [Value] = N'1'), 1, 0);
    DECLARE @new TABLE ([SubmissionId] BIGINT, [PublicId] UNIQUEIDENTIFIER, [Status] VARCHAR (10));
    BEGIN TRY
        BEGIN TRANSACTION;
        INSERT [selfie].[Submission] ([UserId], [Kind], [YourName], [ParentName], [Relation], [CountryCode], [StateName], [City],
            [IsAdult], [GuardianName], [GuardianMobile], [Message], [ConsentedAtUtc], [SourceSubmissionId], [FrameStyle], [Festival],
            [Status], [ReviewNote], [ReviewedAtUtc])
        OUTPUT inserted.[SubmissionId], inserted.[PublicId], inserted.[Status] INTO @new
        SELECT @me, 'frame', s.[YourName], s.[ParentName], s.[Relation], s.[CountryCode], s.[StateName], s.[City],
            s.[IsAdult], s.[GuardianName], s.[GuardianMobile], s.[Message], SYSUTCDATETIME(), s.[SubmissionId], @FrameStyle, @Festival,
            IIF(@auto = 1, 'Approved', 'Pending'), IIF(@auto = 1, N'Auto-approved (photo frames)', NULL), IIF(@auto = 1, SYSUTCDATETIME(), NULL)
        FROM [selfie].[Submission] AS s WHERE s.[SubmissionId] = @source;

        INSERT [selfie].[SubmissionFile] ([SubmissionId], [UserId], [Role], [ContentType], [FileName], [Data], [SizeBytes])
        SELECT n.[SubmissionId], @me, 'main', @PictureType, @PictureName, @PictureData, DATALENGTH(@PictureData) FROM @new AS n;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;   -- never leave the caller with an open transaction
        THROW;
    END CATCH;

    SELECT n.[PublicId], CONCAT('SWP-', RIGHT(CONCAT('000000', n.[SubmissionId]), 6)) AS [Reference], n.[Status] FROM @new AS n;
END;

-- The owner of an approved photo selfie shares it in a photo frame (the framed picture made on the frame page) to the
-- Photo Frames gallery. Only their own selfie: it runs as the caller, and row-level security only shows the caller their
-- own rows. The details are copied from the selfie. It starts as 'Pending' (staff review it like any upload), or — when
-- staff have switched on site setting 'frames.auto-approve' — 'Approved' straight away (staff can still take it down).
-- Returns the reference and the status.
CREATE PROCEDURE [selfie].[usp_ShareFrame]
    @SourcePublicId UNIQUEIDENTIFIER,
    @FrameStyle     VARCHAR (40),
    @Festival       VARCHAR (20),
    @PictureType    VARCHAR (20),
    @PictureData    VARBINARY (MAX),
    @PictureName    NVARCHAR (150)
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50030, N'Please sign in again.', 1;
    IF @VideoData IS NULL
        THROW 50032, N'Add the reel.', 1;
    DECLARE @source BIGINT = (
        SELECT s.[SubmissionId] FROM [selfie].[Submission] AS s
        WHERE s.[PublicId] = @SourcePublicId AND s.[UserId] = @me AND s.[Status] = 'Approved' AND s.[Kind] NOT IN ('frame', 'reel')
          AND EXISTS (SELECT 1 FROM [selfie].[SubmissionFile] AS f WHERE f.[SubmissionId] = s.[SubmissionId] AND f.[Role] = 'main'));
    IF @source IS NULL
        THROW 50037, N'Only your own approved photo selfie can be shared as a reel.', 1;
    IF EXISTS (SELECT 1 FROM [selfie].[Submission] WHERE [SourceSubmissionId] = @source AND [Kind] = 'reel' AND [Status] IN ('Pending', 'Approved'))
        THROW 50038, N'You''ve already shared a reel of this selfie.', 1;
    IF (SELECT COUNT(*) FROM [selfie].[Submission] WHERE [UserId] = @me AND [CreatedAtUtc] > DATEADD(DAY, -1, SYSUTCDATETIME())) >= 10
        THROW 50033, N'You''ve shared 10 times today. Please try again tomorrow.', 1;

    DECLARE @new TABLE ([SubmissionId] BIGINT, [PublicId] UNIQUEIDENTIFIER);
    BEGIN TRY
        BEGIN TRANSACTION;
        INSERT [selfie].[Submission] ([UserId], [Kind], [YourName], [ParentName], [Relation], [CountryCode], [StateName], [City],
            [IsAdult], [GuardianName], [GuardianMobile], [Message], [ConsentedAtUtc], [SourceSubmissionId], [Status], [ReviewNote], [ReviewedAtUtc])
        OUTPUT inserted.[SubmissionId], inserted.[PublicId] INTO @new
        SELECT @me, 'reel', s.[YourName], s.[ParentName], s.[Relation], s.[CountryCode], s.[StateName], s.[City],
            s.[IsAdult], s.[GuardianName], s.[GuardianMobile], s.[Message], SYSUTCDATETIME(), s.[SubmissionId],
            'Approved', N'Auto-approved (reel of an approved selfie)', SYSUTCDATETIME()
        FROM [selfie].[Submission] AS s WHERE s.[SubmissionId] = @source;
        INSERT [selfie].[SubmissionFile] ([SubmissionId], [UserId], [Role], [ContentType], [FileName], [Data], [SizeBytes])
        SELECT n.[SubmissionId], @me, 'video', @VideoType, @VideoName, @VideoData, DATALENGTH(@VideoData) FROM @new AS n;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;   -- never leave the caller with an open transaction
        THROW;
    END CATCH;

    SELECT n.[PublicId], CONCAT('SWP-', RIGHT(CONCAT('000000', n.[SubmissionId]), 6)) AS [Reference] FROM @new AS n;
END;

-- The owner of an approved photo selfie shares its reel (the short video made on the reel page) to the Videos gallery.
-- Only their own selfie (runs as the caller; row-level security only shows the caller their own rows), one reel at a
-- time (one staff took down can be shared again). The details are copied from the selfie. It's approved straight away:
-- the photo in it was already reviewed (staff can still take it down in the review queue).
CREATE PROCEDURE [selfie].[usp_ShareReel]
    @SourcePublicId UNIQUEIDENTIFIER,
    @VideoType      VARCHAR (20),
    @VideoData      VARBINARY (MAX),
    @VideoName      NVARCHAR (150)
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF @me IS NULL OR NOT EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me AND [Status] = 'Active')
        THROW 50080, N'Please sign in again.', 1;
    DECLARE @sub BIGINT, @kind VARCHAR (10), @status VARCHAR (10);
    SELECT @sub = [SubmissionId], @kind = [Kind], @status = [Status] FROM [selfie].[Submission] WHERE [PublicId] = @SelfiePublicId AND [UserId] = @me;
    IF @sub IS NULL OR @status = 'Rejected'
        THROW 50081, N'Choose one of your own selfies.', 1;
    IF @kind NOT IN ('real', 'ai', 'thennow', 'memory')
        THROW 50082, N'Only a selfie with your parent can start a family album.', 1;

    DECLARE @album BIGINT = (SELECT [AlbumId] FROM [selfie].[AlbumSubmission] WHERE [SubmissionId] = @sub);
    IF @album IS NULL
    BEGIN
        DECLARE @code VARCHAR (12), @tries INT = 0;
        WHILE @code IS NULL OR EXISTS (SELECT 1 FROM [selfie].[FamilyAlbum] WHERE [InviteCode] = @code)
        BEGIN
            SET @tries += 1;
            IF @tries > 10 THROW 50089, N'Please try again.', 1;
            -- 10 characters from 31 letters and digits that can't be mixed up (no i, l, o, 0, 1): about 49 bits
            DECLARE @bytes VARBINARY (10) = CRYPT_GEN_RANDOM(10), @i INT = 1;
            SET @code = '';
            WHILE @i <= 10
            BEGIN
                SET @code += SUBSTRING('abcdefghjkmnpqrstuvwxyz23456789', CAST(SUBSTRING(@bytes, @i, 1) AS INT) % 31 + 1, 1);
                SET @i += 1;
            END;
        END;
        BEGIN TRANSACTION;
        INSERT [selfie].[FamilyAlbum] ([InviteCode], [CreatedByUserId]) VALUES (@code, @me);
        SET @album = SCOPE_IDENTITY();
        INSERT [selfie].[AlbumSubmission] ([AlbumId], [SubmissionId]) VALUES (@album, @sub);
        COMMIT;
    END;
    SELECT [PublicId], [InviteCode] FROM [selfie].[FamilyAlbum] WHERE [AlbumId] = @album;
END;

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'site.ContactMessage', COALESCE(i.[ContactMessageId], d.[ContactMessageId]),
           CASE WHEN d.[ContactMessageId] IS NULL THEN 'I' WHEN i.[ContactMessageId] IS NULL THEN 'D' ELSE 'U' END,
           CONCAT(N'Status=', i.[Status]),
           @actor, @scope
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[ContactMessageId] = i.[ContactMessageId];
END;

BEGIN
    SET NOCOUNT ON;
