    DECLARE @actor BIGINT       = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    DECLARE @scope NVARCHAR(20) = CAST(SESSION_CONTEXT(N'AccessScope') AS NVARCHAR(20));
    INSERT [audit].[ChangeLog] ([TableName], [RowKey], [Action], [ChangedColumns], [ActorUserId], [AccessScope])
    SELECT N'site.Setting', COALESCE(i.[SettingId], d.[SettingId]),
           CASE WHEN d.[SettingId] IS NULL THEN 'I' WHEN i.[SettingId] IS NULL THEN 'D' ELSE 'U' END,
           CONCAT(N'Key=', COALESCE(i.[SettingKey], d.[SettingKey]), N',Value=', i.[Value]),
           @actor, @scope
    FROM inserted AS i
    FULL OUTER JOIN deleted AS d ON d.[SettingId] = i.[SettingId];
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage pages.', 1;
    IF EXISTS (SELECT 1 FROM [site].[Page] WHERE [Slug] = @Slug)
        THROW 50022, N'Another page already uses that web address.', 1;

    DECLARE @new TABLE ([PageId] INT);
    BEGIN TRY
        BEGIN TRANSACTION;
        INSERT [site].[Page] ([Slug], [CreatedByUserId], [UpdatedByUserId]) OUTPUT inserted.[PageId] INTO @new VALUES (@Slug, @actor, @actor);
        INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [BlocksJson], [UpdatedByUserId])
        SELECT [PageId], 'en', @Title, N'[]', @actor FROM @new;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;   -- never leave the caller with an open transaction
        THROW;
    END CATCH;
    SELECT [PageId] FROM @new;
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can delete images.', 1;
    IF NOT EXISTS (SELECT 1 FROM [site].[Media] WHERE [PublicId] = @PublicId)
        THROW 50021, N'That image wasn''t found.', 1;
    IF EXISTS (SELECT 1 FROM [site].[Media] WHERE [PublicId] = @PublicId AND [IsSystem] = 1)
        THROW 50027, N'Website pictures can''t be deleted.', 1;
    DELETE [site].[Media] WHERE [PublicId] = @PublicId;
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage menus.', 1;
    IF NOT EXISTS (SELECT 1 FROM [site].[MenuItem] AS i JOIN [site].[Menu] AS m ON m.[MenuId] = i.[MenuId]
                   WHERE i.[MenuItemId] = @MenuItemId AND m.[Audience] = 'Public')
        THROW 50025, N'That menu item wasn''t found.', 1;
    IF EXISTS (SELECT 1 FROM [site].[MenuItem] WHERE [ParentMenuItemId] = @MenuItemId)
        THROW 50024, N'This dropdown still has items in it. Move or delete them first.', 1;
    DELETE [site].[MenuItem] WHERE [MenuItemId] = @MenuItemId;   -- labels go with it (ON DELETE CASCADE)
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage pages.', 1;
    IF NOT EXISTS (SELECT 1 FROM [site].[Page] WHERE [PageId] = @PageId)
        THROW 50021, N'That page wasn''t found.', 1;
    DELETE [site].[Page] WHERE [PageId] = @PageId;   -- its content rows go with it (ON DELETE CASCADE)
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage pages.', 1;
    IF @LanguageCode = 'en'
        THROW 50026, N'The English version can''t be removed.', 1;
    DELETE [site].[PageContent] WHERE [PageId] = @PageId AND [LanguageCode] = @LanguageCode;
END;

-- Removes one translation (the page then shows English in that language). English itself can't be removed.
CREATE PROCEDURE [site].[usp_DeletePageContent]
    @PageId       INT,
    @LanguageCode VARCHAR (5)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage menus.', 1;
    DECLARE @menuId SMALLINT = (SELECT [MenuId] FROM [site].[Menu] WHERE [MenuCode] = @MenuCode AND [Audience] = 'Public');
    IF @menuId IS NULL
        THROW 50025, N'That menu can''t be changed here.', 1;
    IF ISJSON(@ItemsJson) <> 1
        THROW 50023, N'The new order isn''t valid.', 1;

    DECLARE @moves TABLE ([MenuItemId] INT PRIMARY KEY, [ParentMenuItemId] INT NULL, [SortOrder] SMALLINT NOT NULL);
    INSERT @moves SELECT j.[id], j.[parentId], j.[sortOrder]
    FROM OPENJSON(@ItemsJson) WITH ([id] INT '$.id', [parentId] INT '$.parentId', [sortOrder] SMALLINT '$.sortOrder') AS j;

    IF EXISTS (SELECT 1 FROM @moves AS m LEFT JOIN [site].[MenuItem] AS i ON i.[MenuItemId] = m.[MenuItemId] AND i.[MenuId] = @menuId
               WHERE i.[MenuItemId] IS NULL OR m.[SortOrder] IS NULL)
        THROW 50025, N'That menu item wasn''t found.', 1;
    -- Check the menu as it would be AFTER the move: every item's parent must be a top-level dropdown of this menu,
    -- and dropdowns themselves stay at the top level (one level of nesting only)
    DECLARE @after TABLE ([MenuItemId] INT PRIMARY KEY, [ParentMenuItemId] INT NULL, [ItemType] VARCHAR (10) NOT NULL);
    INSERT @after
    SELECT i.[MenuItemId], IIF(m.[MenuItemId] IS NULL, i.[ParentMenuItemId], m.[ParentMenuItemId]), i.[ItemType]
    FROM [site].[MenuItem] AS i LEFT JOIN @moves AS m ON m.[MenuItemId] = i.[MenuItemId]
    WHERE i.[MenuId] = @menuId;
    IF EXISTS (SELECT 1 FROM @after AS a LEFT JOIN @after AS p ON p.[MenuItemId] = a.[ParentMenuItemId]
               WHERE a.[ParentMenuItemId] IS NOT NULL
                 AND (p.[MenuItemId] IS NULL OR p.[ItemType] <> 'Dropdown' OR p.[ParentMenuItemId] IS NOT NULL
                      OR a.[ItemType] = 'Dropdown' OR a.[ParentMenuItemId] = a.[MenuItemId]))
        THROW 50023, N'Items can only go inside a top-level dropdown of the same menu.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;
        UPDATE i SET i.[ParentMenuItemId] = m.[ParentMenuItemId], i.[SortOrder] = m.[SortOrder], i.[UpdatedAtUtc] = SYSUTCDATETIME()
        FROM [site].[MenuItem] AS i JOIN @moves AS m ON m.[MenuItemId] = i.[MenuItemId];
        UPDATE [site].[Menu] SET [UpdatedAtUtc] = SYSUTCDATETIME() WHERE [MenuId] = @menuId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;   -- never leave the caller with an open transaction
        THROW;
    END CATCH;
END;

-- Moves items: [{"id": 12, "parentId": null, "sortOrder": 10}, ...]. Every id must belong to the menu.
CREATE PROCEDURE [site].[usp_ReorderMenu]
    @MenuCode  VARCHAR (30),
    @ItemsJson NVARCHAR (MAX)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can edit the home page.', 1;
    IF @LanguageCode NOT IN ('en', 'hi', 'bn', 'ar', 'es', 'fr')
        THROW 50023, N'Choose a language.', 1;
    IF @ContentJson IS NULL
    BEGIN
        DELETE [site].[HomeContent] WHERE [LanguageCode] = @LanguageCode;
        RETURN;
    END;
    IF ISJSON(@ContentJson) <> 1
        THROW 50023, N'The home page content isn''t valid.', 1;
    UPDATE [site].[HomeContent] SET [ContentJson] = @ContentJson, [UpdatedByUserId] = @actor, [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [LanguageCode] = @LanguageCode;
    IF @@ROWCOUNT = 0
        INSERT [site].[HomeContent] ([LanguageCode], [ContentJson], [UpdatedByUserId]) VALUES (@LanguageCode, @ContentJson, @actor);
END;

-- The home page's content (site.HomeContent). Active SuperAdmin or Admin only (id from the read-only session context);
-- runs as swp_staff_admin; audited by trigger. The API has already checked the JSON's shape.
-- @ContentJson NULL removes the language's content (the website shows its built-in defaults again).
CREATE PROCEDURE [site].[usp_SaveHomeContent]
    @LanguageCode VARCHAR (5),
    @ContentJson  NVARCHAR (MAX)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can upload images.', 1;

    DECLARE @new TABLE ([PublicId] UNIQUEIDENTIFIER);
    INSERT [site].[Media] ([FileName], [ContentType], [Data], [SizeBytes], [CreatedByUserId])
    OUTPUT inserted.[PublicId] INTO @new
    VALUES (@FileName, @ContentType, @Data, DATALENGTH(@Data), @actor);
    SELECT [PublicId] FROM @new;
END;

-- Images for content pages. Same rules as the page procedures (active SuperAdmin or Admin, run as swp_staff_admin).
-- The API checks the file's real type and size before calling; the table checks them again.

CREATE PROCEDURE [site].[usp_SaveMedia]
    @FileName    NVARCHAR (150),
    @ContentType VARCHAR (20),
    @Data        VARBINARY (MAX)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage menus.', 1;

    DECLARE @menuId SMALLINT = (SELECT [MenuId] FROM [site].[Menu] WHERE [MenuCode] = @MenuCode AND [Audience] = 'Public');
    IF @menuId IS NULL
        THROW 50025, N'That menu can''t be changed here.', 1;
    IF @MenuItemId IS NOT NULL AND NOT EXISTS (SELECT 1 FROM [site].[MenuItem] WHERE [MenuItemId] = @MenuItemId AND [MenuId] = @menuId)
        THROW 50025, N'That menu item wasn''t found.', 1;
    IF @ParentMenuItemId IS NOT NULL AND (@ParentMenuItemId = @MenuItemId OR NOT EXISTS (
            SELECT 1 FROM [site].[MenuItem]
            WHERE [MenuItemId] = @ParentMenuItemId AND [MenuId] = @menuId AND [ItemType] = 'Dropdown' AND [ParentMenuItemId] IS NULL))
        THROW 50023, N'Items can only go inside a top-level dropdown of the same menu.', 1;
    IF @ParentMenuItemId IS NOT NULL AND @ItemType = 'Dropdown'
        THROW 50023, N'A dropdown can''t go inside another dropdown.', 1;
    IF @MenuItemId IS NOT NULL AND @ItemType <> 'Dropdown'
       AND EXISTS (SELECT 1 FROM [site].[MenuItem] WHERE [ParentMenuItemId] = @MenuItemId)
        THROW 50024, N'This dropdown still has items in it. Move or delete them first.', 1;
    IF @MenuItemId IS NOT NULL AND @ParentMenuItemId IS NOT NULL
       AND EXISTS (SELECT 1 FROM [site].[MenuItem] WHERE [ParentMenuItemId] = @MenuItemId)
        THROW 50023, N'A dropdown with items can''t go inside another dropdown.', 1;
    IF @LabelsJson IS NOT NULL AND ISJSON(@LabelsJson) <> 1
        THROW 50023, N'The translated labels aren''t valid.', 1;
    IF EXISTS (SELECT 1 FROM [site].[MenuItem] WHERE [MenuId] = @menuId AND [ItemKey] = @ItemKey AND [MenuItemId] <> ISNULL(@MenuItemId, -1))
        THROW 50022, N'Another item in this menu already uses that key.', 1;

    DECLARE @id INT = @MenuItemId;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @id IS NULL
        BEGIN
            DECLARE @new TABLE ([MenuItemId] INT);
            INSERT [site].[MenuItem] ([MenuId], [ItemKey], [ParentMenuItemId], [ItemType], [Label], [Url], [ActionCode], [Icon],
                                      [Visibility], [RequiredRoleId], [OpensNewTab], [SortOrder], [IsActive])
            OUTPUT inserted.[MenuItemId] INTO @new
            VALUES (@menuId, @ItemKey, @ParentMenuItemId, @ItemType, @Label, @Url, @ActionCode, @Icon,
                    @Visibility, NULL, @OpensNewTab, @SortOrder, @IsActive);
            SELECT @id = [MenuItemId] FROM @new;
        END
        ELSE
            UPDATE [site].[MenuItem]
               SET [ItemKey] = @ItemKey, [ParentMenuItemId] = @ParentMenuItemId, [ItemType] = @ItemType, [Label] = @Label,
                   [Url] = @Url, [ActionCode] = @ActionCode, [Icon] = @Icon, [Visibility] = @Visibility,
                   [OpensNewTab] = @OpensNewTab, [SortOrder] = @SortOrder, [IsActive] = @IsActive, [UpdatedAtUtc] = SYSUTCDATETIME()
             WHERE [MenuItemId] = @id;

        DELETE [site].[MenuItemLabel] WHERE [MenuItemId] = @id;
        INSERT [site].[MenuItemLabel] ([MenuItemId], [LanguageCode], [Label])
        SELECT @id, j.[key], LTRIM(RTRIM(j.[value]))
        FROM OPENJSON(ISNULL(@LabelsJson, N'{}')) AS j
        WHERE j.[type] = 1 AND j.[key] IN ('hi', 'bn', 'ar', 'es', 'fr') AND LEN(LTRIM(RTRIM(j.[value]))) > 0;

        UPDATE [site].[Menu] SET [UpdatedAtUtc] = SYSUTCDATETIME() WHERE [MenuId] = @menuId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;   -- never leave the caller with an open transaction
        THROW;
    END CATCH;
    SELECT @id AS [MenuItemId];
END;

-- Public menus (header 'main', footer 'footer'): the only way the website can change them.
-- Staff menus (the admin sidebar) can't be changed here: they stay with the database owner.
-- Same rules as the page procedures: active SuperAdmin or Admin only, run as swp_staff_admin, audited by trigger.
-- The table's own checks still apply (safe links only: site paths, https, mailto, tel).

CREATE PROCEDURE [site].[usp_SaveMenuItem]
    @MenuItemId       INT,              -- NULL = add a new item
    @MenuCode         VARCHAR (30),
    @ParentMenuItemId INT,              -- NULL = top level; otherwise a top-level Dropdown in the same menu
    @ItemKey          VARCHAR (50),
    @ItemType         VARCHAR (10),
    @Label            NVARCHAR (100),   -- English
    @Url              NVARCHAR (300),
    @ActionCode       VARCHAR (30),
    @Icon             VARCHAR (40),
    @Visibility       VARCHAR (10),
    @OpensNewTab      BIT,
    @IsActive         BIT,
    @SortOrder        SMALLINT,
    @LabelsJson       NVARCHAR (MAX)    -- {"hi": "...", "bn": "...", ...}; missing / empty = shows English
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage pages.', 1;
    IF NOT EXISTS (SELECT 1 FROM [site].[Page] WHERE [PageId] = @PageId)
        THROW 50021, N'That page wasn''t found.', 1;
    IF ISJSON(@BlocksJson) <> 1 OR LEFT(LTRIM(@BlocksJson), 1) <> '['
        THROW 50023, N'The page content isn''t valid.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;
        UPDATE [site].[PageContent]
           SET [Title] = @Title, [Description] = NULLIF(LTRIM(RTRIM(@Description)), N''), [BlocksJson] = @BlocksJson,
               [UpdatedAtUtc] = SYSUTCDATETIME(), [UpdatedByUserId] = @actor
         WHERE [PageId] = @PageId AND [LanguageCode] = @LanguageCode;
        IF @@ROWCOUNT = 0
            INSERT [site].[PageContent] ([PageId], [LanguageCode], [Title], [Description], [BlocksJson], [UpdatedByUserId])
            VALUES (@PageId, @LanguageCode, @Title, NULLIF(LTRIM(RTRIM(@Description)), N''), @BlocksJson, @actor);
        UPDATE [site].[Page] SET [UpdatedAtUtc] = SYSUTCDATETIME(), [UpdatedByUserId] = @actor WHERE [PageId] = @PageId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;   -- never leave the caller with an open transaction
        THROW;
    END CATCH;
END;

CREATE PROCEDURE [site].[usp_SavePageContent]
    @PageId       INT,
    @LanguageCode VARCHAR (5),
    @Title        NVARCHAR (120),
    @Description  NVARCHAR (300),
    @BlocksJson   NVARCHAR (MAX)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @me BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    SET @Name = NULLIF(LTRIM(RTRIM(@Name)), N'');
    SET @Email = LOWER(NULLIF(LTRIM(RTRIM(@Email)), N''));
    SET @Subject = NULLIF(LTRIM(RTRIM(@Subject)), N'');
    SET @Message = NULLIF(LTRIM(RTRIM(@Message)), N'');
    IF @Name IS NULL OR @Email IS NULL OR @Message IS NULL
        THROW 50023, N'Please fill in your name, email and message.', 1;
    IF (SELECT COUNT(*) FROM [site].[ContactMessage] WHERE [Email] = @Email AND [CreatedAtUtc] > DATEADD(HOUR, -1, SYSUTCDATETIME())) >= 3
        OR (SELECT COUNT(*) FROM [site].[ContactMessage] WHERE [CreatedAtUtc] > DATEADD(HOUR, -1, SYSUTCDATETIME())) >= 300
        THROW 50026, N'Thanks — we already have your message. Please try again in an hour.', 1;
    DECLARE @new TABLE ([PublicId] UNIQUEIDENTIFIER);
    INSERT [site].[ContactMessage] ([Name], [Email], [Subject], [Message], [UserId])
    OUTPUT inserted.[PublicId] INTO @new
    VALUES (@Name, @Email, @Subject, @Message, IIF(EXISTS (SELECT 1 FROM [auth].[User] WHERE [UserId] = @me), @me, NULL));
    SELECT [PublicId] FROM @new;
END;

-- The website's contact form and its inbox in the admin site. Errors 50020-50029 are shown to the user.

-- Anyone sends a message with the contact form (the API calls this in System scope for visitors who aren't signed in,
-- or as the signed-in visitor). Spam limits: 3 messages per email address per hour, 300 per hour in all.
CREATE PROCEDURE [site].[usp_SendContactMessage]
    @Name    NVARCHAR (60),
    @Email   NVARCHAR (254),
    @Subject NVARCHAR (100),
    @Message NVARCHAR (1000)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage messages.', 1;
    IF @Status NOT IN ('New', 'Read', 'Archived')
        THROW 50023, N'Choose New, Read or Archived.', 1;
    UPDATE [site].[ContactMessage]
       SET [Status] = @Status,
           [ReadAtUtc] = IIF(@Status = 'New', NULL, ISNULL([ReadAtUtc], SYSUTCDATETIME())),
           [ReadByUserId] = IIF(@Status = 'New', NULL, ISNULL([ReadByUserId], @actor))
     WHERE [PublicId] = @PublicId;
    IF @@ROWCOUNT = 0
        THROW 50025, N'That message wasn''t found.', 1;
END;

-- A super admin / admin marks a message Read, back to New, or Archived.
CREATE PROCEDURE [site].[usp_SetContactMessageStatus]
    @PublicId UNIQUEIDENTIFIER,
    @Status   VARCHAR (10)
WITH EXECUTE AS N'swp_staff_admin'
AS

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can change settings.', 1;
    IF @SettingKey NOT IN ('frames.auto-approve', 'donations.enabled', 'contact.email', 'contact.phone', 'contact.address',
        'feature.then-now', 'feature.memories', 'feature.family-tree', 'feature.contest', 'feature.photo-frames', 'feature.reels', 'feature.parents-voices', 'feature.support', 'feature.streaks', 'feature.profiles', 'feature.albums', 'show.contact-email', 'show.contact-phone', 'show.contact-address')
        THROW 50025, N'That setting wasn''t found.', 1;
    SET @Value = LTRIM(RTRIM(ISNULL(@Value, N'')));
    IF @SettingKey = 'contact.email' AND @Value <> N'' AND (@Value NOT LIKE '%_@_%._%' OR @Value LIKE '% %')
        THROW 50023, N'Enter a valid email address.', 1;
    IF @SettingKey = 'contact.phone' AND @Value COLLATE Latin1_General_BIN2 LIKE '%[^0-9+ ()-]%'
        THROW 50023, N'A phone number can only have digits, spaces, +, - and brackets.', 1;
    IF @Value LIKE '%[<>]%'
        THROW 50023, N'Text can''t contain < or >.', 1;

    UPDATE [site].[Setting] SET [Value] = @Value, [UpdatedByUserId] = @actor, [UpdatedAtUtc] = SYSUTCDATETIME()
     WHERE [SettingKey] = @SettingKey;
    IF @@ROWCOUNT = 0
        INSERT [site].[Setting] ([SettingKey], [Value], [UpdatedByUserId]) VALUES (@SettingKey, @Value, @actor);
END;

BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @actor BIGINT = TRY_CAST(SESSION_CONTEXT(N'UserId') AS BIGINT);
    IF NOT EXISTS (SELECT 1 FROM [auth].[fn_ActiveRoles](@actor) WHERE [RoleCode] IN ('SuperAdmin', 'Admin'))
        THROW 50020, N'Only a super admin or admin can manage pages.', 1;
    IF NOT EXISTS (SELECT 1 FROM [site].[Page] WHERE [PageId] = @PageId)
        THROW 50021, N'That page wasn''t found.', 1;
    IF EXISTS (SELECT 1 FROM [site].[Page] WHERE [Slug] = @Slug AND [PageId] <> @PageId)
        THROW 50022, N'Another page already uses that web address.', 1;

    UPDATE [site].[Page]
       SET [Slug] = @Slug, [IsPublished] = @IsPublished, [UpdatedAtUtc] = SYSUTCDATETIME(), [UpdatedByUserId] = @actor
     WHERE [PageId] = @PageId;
END;

CREATE PROCEDURE [site].[usp_UpdatePage]
    @PageId      INT,
    @Slug        VARCHAR (60),
    @IsPublished BIT
WITH EXECUTE AS N'swp_staff_admin'
AS
